export type WelcomeTextsProps = {
  className: string;
  titleSrc: string;
  titleClassName: string;
  descriptionSrc: string;
  descriptionClassName: string;
};

/** Welcome title/header + description image pair. */
export function WelcomeTexts({
  className,
  titleSrc,
  titleClassName,
  descriptionSrc,
  descriptionClassName,
}: WelcomeTextsProps) {
  return (
    <div className={className} aria-hidden>
      <img
        className={titleClassName}
        src={titleSrc}
        alt=""
        draggable={false}
      />
      <img
        className={descriptionClassName}
        src={descriptionSrc}
        alt=""
        draggable={false}
      />
    </div>
  );
}
