import './MuteToggleButton.css';

export type MuteToggleButtonProps = {
  muted: boolean;
  onClick?: () => void;
};

/** Minimal mute toggle for PauseScreen (no Figma asset yet). */
export function MuteToggleButton({ muted, onClick }: MuteToggleButtonProps) {
  return (
    <button
      type="button"
      className="pause-mute-toggle"
      aria-label={muted ? 'Включить звук' : 'Выключить звук'}
      aria-pressed={muted}
      onClick={onClick}
    >
      {muted ? 'Звук: выкл' : 'Звук: вкл'}
    </button>
  );
}
