import claudiStickerImg from './claudi_sticker.png';
import './ClaudiSticker.css';

/** Claudi reward sticker — 29.67 1146.41 341×355. */
export function ClaudiSticker() {
  return (
    <img
      className="sticker-reward-claudi"
      src={claudiStickerImg}
      alt=""
      draggable={false}
      aria-hidden
    />
  );
}
