import { DeliveryItemImage } from '../../components/atomic/delivery_items/DeliveryItemImage';
import type { GiantIconName } from '../../components/atomic/giants/giant_icons/GiantIcon';
import { getDeliveryCardGiantLayout } from '../../components/atomic/giants/giant_icons/deliveryCardGiantLayouts';
import { GIANT_BADGE_ICONS } from '../../components/atomic/giants/giant_icons/giantIconAssets';
import '../../components/atomic/giants/giant_icons/GiantIcon.css';
import { GIANT_IDS } from '../../../../domain/ids/ids';
import {
  DELIVERY_CARD_BACKGROUND_URL,
  DELIVERY_CARD_CLOSED_FRAME_URL,
  DELIVERY_CARD_OPENED_BACKGROUND_URL,
  DELIVERY_CARD_DECOR_LABEL_URL,
  DELIVERY_CARD_GIANT_NAME_TEXT_URL,
  DELIVERY_CARD_LEVEL_NAME_TEXT_URL,
} from './deliveryCardAssets';
import './DeliveryCard.css';

export type DeliveryCardItemFrame = 'opened' | 'closed';

export type DeliveryCardProps = {
  /** Id гиганта для иконки в плашке. */
  giantId?: GiantIconName;
  /** Индекс заказа гиганта (0-based). */
  orderIndex?: number;
  /** Кадр предмета внутри плашки: открытый фон или закрытая рамка. */
  itemFrame?: DeliveryCardItemFrame;
  levelNameText?: string;
  giantNameText?: string;
  onClick?: () => void;
};

/**
 * Плашка карточки доставки + кадр предмета + подписи (Figma delivery_good 157:7001).
 * Plaque: Top 746, Height 548. Item: Left 482.9707, Top 1009.5313.
 * Giant: shared yetti box from deliveryCardGiantLayouts.
 * Level name (188:9268): screen 235.5 759.90625 606×64, Matias 54px.
 */
export function DeliveryCard({
  giantId = 'roza',
  orderIndex = 0,
  itemFrame = 'closed',
  levelNameText,
  giantNameText,
  onClick,
}: DeliveryCardProps) {
  const itemSrc =
    itemFrame === 'opened'
      ? DELIVERY_CARD_OPENED_BACKGROUND_URL
      : DELIVERY_CARD_CLOSED_FRAME_URL;
  const isClickable = onClick != null;
  const giantLayout = getDeliveryCardGiantLayout(giantId);

  return (
    <div
      className={[
        'delivery-card',
        isClickable ? 'delivery-card--clickable' : undefined,
      ]
        .filter(Boolean)
        .join(' ')}
      role={isClickable ? 'button' : undefined}
      tabIndex={isClickable ? 0 : undefined}
      aria-hidden={isClickable ? undefined : true}
      onClick={onClick}
      onKeyDown={
        isClickable
          ? (event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                onClick();
              }
            }
          : undefined
      }
    >
      <img
        className="delivery-card__background"
        src={DELIVERY_CARD_BACKGROUND_URL}
        alt=""
        draggable={false}
      />
      {/* All giant arts stay mounted; only the selected one is visible. */}
      {GIANT_IDS.map((id) => {
        const isSelected = id === giantId;
        return (
          <img
            key={id}
            className={[
              'giant-icon',
              'delivery-card__giant',
              isSelected ? null : 'giant-icon--hidden',
            ]
              .filter(Boolean)
              .join(' ')}
            style={{
              left: giantLayout.left,
              top: giantLayout.top,
              width: giantLayout.width,
              height: giantLayout.height,
            }}
            src={GIANT_BADGE_ICONS[id]}
            alt=""
            draggable={false}
            aria-hidden={!isSelected}
          />
        );
      })}
      <div className="delivery-card__giant-name-bg" />
      <div className="delivery-card__decor-label-bg" />
      <img
        className="delivery-card__item"
        src={itemSrc}
        alt=""
        draggable={false}
      />
      <DeliveryItemImage
        giantId={giantId}
        orderIndex={orderIndex}
        placement="delivery-card"
        hidden={itemFrame !== 'opened'}
      />
      {levelNameText ? (
        <svg
          className="delivery-card__level-name delivery-card__level-name--live"
          width={606}
          height={64}
          viewBox="0 0 606 64"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          aria-hidden
        >
          <text
            className="delivery-card__level-name-text"
            textAnchor="middle"
            xmlSpace="preserve"
          >
            <tspan x={303} y={52}>
              {levelNameText}
            </tspan>
          </text>
        </svg>
      ) : (
        <img
          className="delivery-card__level-name"
          src={DELIVERY_CARD_LEVEL_NAME_TEXT_URL}
          alt="Спиночесалка"
          draggable={false}
        />
      )}
      {giantNameText ? (
        <svg
          className="delivery-card__giant-name delivery-card__giant-name--live"
          width={276}
          height={38}
          viewBox="0 0 276 38"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          aria-hidden
        >
          <text
            className="delivery-card__giant-name-text"
            textAnchor="middle"
            xmlSpace="preserve"
          >
            <tspan x={138} y={31}>
              {giantNameText}
            </tspan>
          </text>
        </svg>
      ) : (
        <img
          className="delivery-card__giant-name"
          src={DELIVERY_CARD_GIANT_NAME_TEXT_URL}
          alt="Обсерватория Роза"
          draggable={false}
        />
      )}
      <img
        className="delivery-card__decor-label"
        src={DELIVERY_CARD_DECOR_LABEL_URL}
        alt="Что внутри"
        draggable={false}
      />
    </div>
  );
}
