export const UNLOCKED_LEVELS_MAX = 9;

/** @deprecated Используйте {@link GIANT_UNLOCK_AVG_RATING}. */
export const RATING_PER_UNLOCK = 10;

/** Минимальный средний рейтинг для открытия гиганта по индексу (0 — всегда открыт). */
export const GIANT_UNLOCK_AVG_RATING: readonly number[] = [
  0, 0.5, 1.4, 2.2, 2.9, 3.4, 3.8, 4.1, 4.4, 4.6,
];

/** Идеальная доставка (100%). */
export const PERFECT_DELIVERY_RATING = 5;

/** Срочный заказ истекает через 6 часов после появления в пуле. */
