/** @deprecated Используйте {@link passRewardForDelivery}. */
export const URGENT_DELIVERY_PASS_REWARD = 3;

/**
 * Награды улетными билетами за ежедневный вход (GDD v2: «Вход 7 дней подряд»).
 * День 1 → 1 билет, …, день 7 → 7 билетов.
 */
export const DAILY_LOGIN_PASS_REWARDS: readonly number[] = [1, 2, 3, 4, 5, 6, 7];

export function dailyLoginPassRewardForStreakDay(streakDay: number): number {
  const day = Math.max(1, Math.min(7, Math.floor(streakDay)));
  return DAILY_LOGIN_PASS_REWARDS[day - 1] ?? 1;
}

/** За включение уведомлений в игре (GDD v2). */
export const NOTIFICATIONS_PASS_REWARD = 3;

/** За бизнес-задания: подписка, приглашение друга и т.п. (GDD v2). */
export const BUSINESS_TASK_PASS_REWARD = 1;
