import './FrameHeader.css';

type FrameHeaderProps = {
  /** Visibility of sub_header_background (118:6772). Default: true. */
  showSubHeader?: boolean;
};

/** From Figma header (119:6946) — sub_header + header_background. */
export function FrameHeader({ showSubHeader = true }: FrameHeaderProps) {
  return (
    <div className="frame-header" aria-hidden>
      {showSubHeader ? <div className="frame-header__sub" /> : null}
      <div className="frame-header__main" />
    </div>
  );
}
