import {
  buildMuMeteorObstacles,
  hasActiveMuMeteorObstacles,
} from '../../domain/runner/muMeteorPaths';
import {
  buildYettiIceObstacles,
  hasActiveYettiIceObstacles,
  poseYettiStyleObstacle,
} from '../../domain/runner/yettiIcePaths';
import {
  buildRozaModifierObstacles,
  hasActiveRozaModifierObstacles,
} from '../../domain/runner/rozaObstaclePaths';
import type {
  RunnerCyclicPhase,
  RunnerCyclicVisibilityMotion,
  RunnerLevel,
  RunnerObstacle,
} from '../../domain/runner/runnerTypes';

/** Спавн метеоритов mu при enter зоны модификатора (один раз). */
export function spawnMuModifierObstacles(level: RunnerLevel): RunnerLevel {
  if (level.giantId !== 'mu') {
    return level;
  }
  if (hasActiveMuMeteorObstacles(level)) {
    return level;
  }
  const meteors = buildMuMeteorObstacles(level);
  if (meteors.length === 0) {
    return level;
  }
  return {
    ...level,
    obstacles: [...level.obstacles, ...meteors],
  };
}

/** Спавн up/bottom ice yetti при enter зоны модификатора (один раз). */
export function spawnYettiModifierObstacles(level: RunnerLevel): RunnerLevel {
  if (level.giantId !== 'yetti') {
    return level;
  }
  if (hasActiveYettiIceObstacles(level)) {
    return level;
  }
  const ice = buildYettiIceObstacles(level);
  if (ice.length === 0) {
    return level;
  }
  return {
    ...level,
    obstacles: [...level.obstacles, ...ice],
  };
}

/** Спавн цикличных препятствий roza при enter зоны модификатора (один раз). */
export function spawnRozaModifierObstacles(level: RunnerLevel): RunnerLevel {
  if (level.giantId !== 'roza') {
    return level;
  }
  if (hasActiveRozaModifierObstacles(level)) {
    return level;
  }
  const obstacles = buildRozaModifierObstacles(level);
  if (obstacles.length === 0) {
    return level;
  }
  return {
    ...level,
    obstacles: [...level.obstacles, ...obstacles],
  };
}

function advanceCyclicPhase(phase: RunnerCyclicPhase): RunnerCyclicPhase {
  switch (phase) {
    case 'visible':
      return 'fadeOut';
    case 'fadeOut':
      return 'hidden';
    case 'hidden':
      return 'fadeIn';
    case 'fadeIn':
      return 'visible';
  }
}

function cyclicPhaseDuration(motion: RunnerCyclicVisibilityMotion): number {
  switch (motion.phase) {
    case 'visible':
      return motion.visibleSec;
    case 'hidden':
      return motion.hiddenSec;
    case 'fadeOut':
    case 'fadeIn':
      return motion.fadeSec;
  }
}

function cyclicOpacity(phase: RunnerCyclicPhase, t: number): number {
  switch (phase) {
    case 'visible':
      return 1;
    case 'hidden':
      return 0;
    case 'fadeOut':
      return 1 - t;
    case 'fadeIn':
      return t;
  }
}

function tickCyclicObstacle(
  obstacle: RunnerObstacle,
  motion: RunnerCyclicVisibilityMotion,
  deltaSeconds: number,
  motionScale: number,
): RunnerObstacle {
  if (motionScale <= 0 || deltaSeconds <= 0) {
    return obstacle;
  }

  let phase = motion.phase;
  let elapsedSec = motion.elapsedSec + deltaSeconds * motionScale;
  let opacity: number;

  while (true) {
    if (elapsedSec < 0) {
      opacity = cyclicOpacity(phase, 0);
      break;
    }
    const duration = cyclicPhaseDuration({ ...motion, phase });
    if (duration <= 0 || elapsedSec >= duration) {
      elapsedSec -= Math.max(duration, 0);
      phase = advanceCyclicPhase(phase);
      continue;
    }
    const t = phase === 'fadeOut' || phase === 'fadeIn' ? elapsedSec / duration : 0;
    opacity = cyclicOpacity(phase, t);
    break;
  }

  return {
    ...obstacle,
    opacity,
    motion: {
      ...motion,
      phase,
      elapsedSec,
    },
  };
}

function tickPathObstacle(
  obstacle: RunnerObstacle,
  deltaSeconds: number,
  motionScale: number,
): RunnerObstacle {
  const motion = obstacle.motion;
  if (motion == null || obstacle.consumed) {
    return obstacle;
  }
  if (motion.kind === 'cyclic') {
    return tickCyclicObstacle(obstacle, motion, deltaSeconds, motionScale);
  }
  if (motion.kind !== 'path') {
    return obstacle;
  }
  if (motionScale <= 0) {
    return obstacle;
  }
  if (motion.elapsedSec >= motion.durationSec) {
    return obstacle;
  }

  const elapsedSec = Math.min(
    motion.durationSec,
    motion.elapsedSec + deltaSeconds * motionScale,
  );
  const t =
    motion.durationSec <= 0 ? 1 : Math.min(1, elapsedSec / motion.durationSec);
  const visualCenterS = motion.startS + (motion.finishS - motion.startS) * t;
  const visualCenterLane =
    motion.startLane + (motion.finishLane - motion.startLane) * t;
  const arrived = t >= 1;
  const consumeOnArrive = motion.consumeOnArrive !== false;

  const withPose =
    obstacle.hitboxLaneOffset != null ||
    obstacle.visualWidthS != null ||
    obstacle.visualCenterS != null
      ? poseYettiStyleObstacle(obstacle, visualCenterS, visualCenterLane)
      : {
          ...obstacle,
          hitbox: {
            ...obstacle.hitbox,
            centerS: visualCenterS,
            centerLane: visualCenterLane,
          },
        };

  return {
    ...withPose,
    consumed: arrived && consumeOnArrive ? true : obstacle.consumed,
    motion: {
      ...motion,
      elapsedSec,
    },
  };
}

/** Движение path-препятствий; возвращает тот же level, если ничего не изменилось. */
export function tickRunnerPathObstaclesUseCase(
  level: RunnerLevel,
  deltaSeconds: number,
  motionScale = 1,
): RunnerLevel {
  let changed = false;
  const obstacles = level.obstacles.map((obstacle) => {
    const next = tickPathObstacle(obstacle, deltaSeconds, motionScale);
    if (next !== obstacle) {
      changed = true;
    }
    return next;
  });
  if (!changed) {
    return level;
  }
  return { ...level, obstacles };
}
