import buttonTextImg from './texts/button_text.png';
import { DELIVERY_POPUP_LAYOUT } from './deliveryPopupLayout';
import './TakeDeliveryButton.css';

export type TakeDeliveryButtonProps = {
  onClick?: () => void;
};

/** Figma take_delivery_button (180:104) — compact map popup CTA. */
export function TakeDeliveryButton({ onClick }: TakeDeliveryButtonProps) {
  const button = DELIVERY_POPUP_LAYOUT.takeDeliveryButton;

  return (
    <button
      type="button"
      className="take-delivery-button"
      aria-label="Взять заказ"
      onClick={onClick}
      style={{
        width: button.width,
        height: button.height,
        ['--take-btn-text-width' as string]: `${button.textWidth}px`,
        ['--take-btn-text-height' as string]: `${button.textHeight}px`,
      }}
    >
      <img
        className="take-delivery-button__text"
        src={buttonTextImg}
        alt=""
        draggable={false}
      />
    </button>
  );
}
