import type {
  RunnerDecorSprite,
  RunnerLevel,
  RunnerObstacle,
  RunnerYettiObstacleSpriteKey,
} from './runnerTypes';

/** Смещение полосы геймплея в Yeti.svg (`translate(0 719.059)`). */
export const YETTI_PLAY_STRIP_OFFSET_Y = 719.059;

/** Высота полосы геймплея в Yeti.svg. */
export const YETTI_PLAY_STRIP_HEIGHT = 929.588;

/** Длительность подъезда ice start→finish, сек. */
export const YETTI_ICE_FLIGHT_DURATION_SEC = 2;

type YettiIcePathDef = {
  id: string;
  spriteKey: RunnerYettiObstacleSpriteKey;
  startSvgX: number;
  startSvgY: number;
  finishSvgX: number;
  finishSvgY: number;
  widthSvg: number;
  heightSvg: number;
  /**
   * Смещение hitbox.centerLane относительно visual center.
   * up: +0.25·heightLane (к потолку), bottom: −0.25·heightLane (к полу).
   */
  hitboxLaneOffsetSign: 1 | -1;
};

/** Пути из Yeti.svg: up/bottom start→finish (centers bbox). */
export const YETTI_ICE_PATHS: readonly YettiIcePathDef[] = [
  {
    id: 'yetti_up',
    spriteKey: 'yetti_up',
    startSvgX: 6835.08,
    startSvgY: 224.38,
    finishSvgX: 6821.82,
    finishSvgY: 848.38,
    widthSvg: 2237.34,
    heightSvg: 448.75,
    hitboxLaneOffsetSign: 1,
  },
  {
    id: 'yetti_bottom',
    spriteKey: 'yetti_bottom',
    startSvgX: 6793.33,
    startSvgY: 1962.17,
    finishSvgX: 6793.33,
    finishSvgY: 1545.83,
    widthSvg: 2283.84,
    heightSvg: 518.35,
    hitboxLaneOffsetSign: -1,
  },
] as const;

const FOAM_SVG = {
  id: 'yetti_foam',
  x: 5696.41,
  y: 524,
  width: 2250,
  height: 1327,
} as const;

export function yettiSvgYToLane(absoluteSvgY: number): number {
  const localY = absoluteSvgY - YETTI_PLAY_STRIP_OFFSET_Y;
  return 1 - localY / YETTI_PLAY_STRIP_HEIGHT;
}

export function yettiSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function visualHeightLane(heightSvg: number): number {
  return heightSvg / YETTI_PLAY_STRIP_HEIGHT;
}

function applyVisualPose(
  visualCenterS: number,
  visualCenterLane: number,
  widthSvg: number,
  heightSvg: number,
  hitboxLaneOffsetSign: 1 | -1,
): Pick<
  RunnerObstacle,
  | 'hitbox'
  | 'visualWidthS'
  | 'visualHeightLane'
  | 'visualCenterS'
  | 'visualCenterLane'
  | 'hitboxLaneOffset'
> {
  const heightLane = visualHeightLane(heightSvg);
  const hitboxLaneOffset = hitboxLaneOffsetSign * 0.25 * heightLane;
  return {
    visualWidthS: widthSvg,
    visualHeightLane: heightLane,
    visualCenterS,
    visualCenterLane,
    hitboxLaneOffset,
    hitbox: {
      centerS: visualCenterS,
      centerLane: visualCenterLane + hitboxLaneOffset,
      widthS: widthSvg,
      heightLane: heightLane * 0.5,
    },
  };
}

export function buildYettiFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'yetti') {
    return [];
  }
  const cx = FOAM_SVG.x + FOAM_SVG.width / 2;
  const cy = FOAM_SVG.y + FOAM_SVG.height / 2;
  return [
    {
      id: FOAM_SVG.id,
      spriteKey: 'yetti_foam',
      centerS: yettiSvgXToS(cx, level.startPointSvgX),
      centerLane: yettiSvgYToLane(cy),
      widthS: FOAM_SVG.width,
      heightLane: visualHeightLane(FOAM_SVG.height),
    },
  ];
}

export function buildYettiIceObstacles(level: RunnerLevel): RunnerObstacle[] {
  const { startPointSvgX } = level;
  return YETTI_ICE_PATHS.map((path) => {
    const startS = yettiSvgXToS(path.startSvgX, startPointSvgX);
    const startLane = yettiSvgYToLane(path.startSvgY);
    const finishS = yettiSvgXToS(path.finishSvgX, startPointSvgX);
    const finishLane = yettiSvgYToLane(path.finishSvgY);
    const pose = applyVisualPose(
      startS,
      startLane,
      path.widthSvg,
      path.heightSvg,
      path.hitboxLaneOffsetSign,
    );
    return {
      id: path.id,
      anchorS: startS,
      spriteKey: path.spriteKey,
      consumed: false,
      collides: false,
      ...pose,
      motion: {
        kind: 'path',
        startS,
        startLane,
        finishS,
        finishLane,
        durationSec: YETTI_ICE_FLIGHT_DURATION_SEC,
        elapsedSec: 0,
        consumeOnArrive: false,
      },
    };
  });
}

export function hasActiveYettiIceObstacles(level: RunnerLevel): boolean {
  const ids = new Set(YETTI_ICE_PATHS.map((p) => p.id));
  return level.obstacles.some((o) => ids.has(o.id) && !o.consumed);
}

/** Обновить hitbox из visual center + offset (используется тиком). */
export function poseYettiStyleObstacle(
  obstacle: RunnerObstacle,
  visualCenterS: number,
  visualCenterLane: number,
): RunnerObstacle {
  const offset = obstacle.hitboxLaneOffset ?? 0;
  return {
    ...obstacle,
    visualCenterS,
    visualCenterLane,
    hitbox: {
      ...obstacle.hitbox,
      centerS: visualCenterS,
      centerLane: visualCenterLane + offset,
    },
  };
}
