import type { RunnerDecorSprite, RunnerLevel, RunnerObstacle, RunnerSvamiObstacleSpriteKey } from './runnerTypes';

type SvamiObstacleDef = {
  id: string;
  spriteKey: RunnerSvamiObstacleSpriteKey;
  /** Центр bbox path в svami/modificators.svg (`<g id="1">`..`<g id="3">`, без blur-паддинга фильтра). */
  centerSvgX: number;
  centerSvgY: number;
  widthSvg: number;
  heightSvg: number;
};

/** Период покачивания static.png, сек. Слегка разный у соседних, чтобы не синхронизировались. */
const SVAMI_STATIC_WOBBLE_DURATIONS_SEC = [2.2, 2.4, 2.6, 2.8] as const;

export function svamiStaticWobbleDurationSec(index: number): number {
  return SVAMI_STATIC_WOBBLE_DURATIONS_SEC[index % SVAMI_STATIC_WOBBLE_DURATIONS_SEC.length];
}

/** Позиции из svami/modificators.svg: центры bbox групп `1`..`3`. */
export const SVAMI_OBSTACLE_DEFS: readonly SvamiObstacleDef[] = [
  { id: 'svami_1', spriteKey: 'svami_1', centerSvgX: 6821.34, centerSvgY: 877.26, widthSvg: 442.37, heightSvg: 522.26 },
  { id: 'svami_2', spriteKey: 'svami_2', centerSvgX: 7453.78, centerSvgY: 713.69, widthSvg: 822.47, heightSvg: 1082.25 },
  { id: 'svami_3', spriteKey: 'svami_3', centerSvgX: 6310.15, centerSvgY: 625.22, widthSvg: 1099.48, heightSvg: 1104.00 },
] as const;

/** Прямоугольник `#foam` из svami/modificators.svg (raw rect, без учёта blur-фильтра). */
const SVAMI_FOAM_SVG = {
  id: 'svami_foam',
  x: 5722.96,
  y: -168.867,
  width: 2210.9,
  height: 1314.36,
} as const;

function svamiSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function svamiSvgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

/** Препятствия svami: статичные, без коллизии, поверх игрока (layer: 'front'). */
export function buildSvamiObstacles(level: RunnerLevel): RunnerObstacle[] {
  if (level.giantId !== 'svami') {
    return [];
  }
  return SVAMI_OBSTACLE_DEFS.map((def) => {
    const centerS = svamiSvgXToS(def.centerSvgX, level.startPointSvgX);
    const centerLane = svamiSvgYToLane(def.centerSvgY, level.viewBox.height);
    return {
      id: def.id,
      anchorS: centerS,
      spriteKey: def.spriteKey,
      layer: 'front',
      consumed: false,
      collides: false,
      hitbox: {
        centerS,
        centerLane,
        widthS: def.widthSvg,
        heightLane: def.heightSvg / level.viewBox.height,
      },
    };
  });
}

/** Foam svami: статичный неколлизионный декор поверх игрока. */
export function buildSvamiFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'svami') {
    return [];
  }
  const cx = SVAMI_FOAM_SVG.x + SVAMI_FOAM_SVG.width / 2;
  const cy = SVAMI_FOAM_SVG.y + SVAMI_FOAM_SVG.height / 2;
  return [
    {
      id: SVAMI_FOAM_SVG.id,
      spriteKey: 'svami_foam',
      centerS: svamiSvgXToS(cx, level.startPointSvgX),
      centerLane: svamiSvgYToLane(cy, level.viewBox.height),
      widthS: SVAMI_FOAM_SVG.width,
      heightLane: SVAMI_FOAM_SVG.height / level.viewBox.height,
      layer: 'front',
    },
  ];
}
