import type { ReactNode } from 'react';
import '../../../atomic/layout/app_screen/app_screen.css';
import { DialogPopup } from '../../../atomic/dialog/dialog_popup/DialogPopup';
import { PagePaginator } from '../../../atomic/buttons/page_paginator/PagePaginator';
import { SkyAtmosphere } from '../../atmosphere/sky_atmosphere/SkyAtmosphere';

export type WelcomeShellProps = {
  className: string;
  paginatorCurrent: number;
  /** Between atmosphere and DialogPopup (e.g. welcome_1 Character). */
  beforeDialog?: ReactNode;
  /** After DialogPopup, before paginator (texts, decor, character). */
  afterDialog?: ReactNode;
  button: ReactNode;
};

/** Shared welcome sky + dialog popup + paginator with content slots. */
export function WelcomeShell({
  className,
  paginatorCurrent,
  beforeDialog,
  afterDialog,
  button,
}: WelcomeShellProps) {
  return (
    <div className={['app-screen', className].filter(Boolean).join(' ')}>
      <SkyAtmosphere variant="welcome" />
      {beforeDialog}
      <DialogPopup />
      {afterDialog}
      <PagePaginator current={paginatorCurrent} />
      {button}
    </div>
  );
}
