import type { DeliveryRatingBreakdown } from '../../../domain';
import type { GiantId } from '../../../domain/ids/ids';

export type DeliveryResultScreenProps = {
  giantId?: GiantId;
  orderIndex?: number;
  rating?: DeliveryRatingBreakdown | null;
  onRestart?: () => void;
  onGoHome?: () => void;
  canRestart?: boolean;
};

export type DeliveryResultScreenModel = {
  giantId?: GiantId;
  orderIndex: number;
  rating: DeliveryRatingBreakdown | null;
  onRestart?: () => void;
  onGoHome?: () => void;
  canRestart: boolean;
};

export function createDeliveryResultScreenModel(
  props: DeliveryResultScreenProps,
): DeliveryResultScreenModel {
  return {
    giantId: props.giantId,
    orderIndex: props.orderIndex ?? 0,
    rating: props.rating ?? null,
    onRestart: props.onRestart,
    onGoHome: props.onGoHome,
    canRestart: props.canRestart !== false,
  };
}
