function imageSrcForQuestionId(questionId: string | undefined): string {
  if (questionId == null) {
    return quizImageFallback;
  }
  const match = /^quiz_(\d+)$/.exec(questionId);
  if (match == null) {
    return quizImageFallback;
  }
  return QUIZ_IMAGES_BY_NUMBER.get(Number(match[1])) ?? quizImageFallback;
}

export type QuizImageProps = {
  questionId?: string;
};

/** Figma image 171 (161:23931) — quiz illustration with white frame. */
export function QuizImage({ questionId }: QuizImageProps) {
  return (
    <img
      className="quiz-image"
      src={imageSrcForQuestionId(questionId)}
      alt=""
      draggable={false}
    />
  );
}
