import './HealthBar.css';
import emptyHeartImg from './content/icon_empty_heart.png';
import heartImg from './content/icon_heart.png';

/** Figma hearts (130:21442) — 5 slots on 1080×1920 viewport. */
const HEART_SLOTS = [
  { left: 592, top: 304 },
  { left: 675.7539, top: 304 },
  { left: 759.5076, top: 304 },
  { left: 843.2615, top: 304 },
  { left: 927.0151, top: 306 },
] as const;

const HEART_WIDTH = 65.7538;
const HEART_HEIGHT = 58.2608;

export type HealthBarProps = {
  /** Current health (filled hearts). */
  value?: number;
  /** Max health (total hearts). Capped by layout slots. */
  max?: number;
  className?: string;
};

export function HealthBar({
  value = 4,
  max = HEART_SLOTS.length,
  className,
}: HealthBarProps) {
  const slotCount = Math.min(Math.max(max, 0), HEART_SLOTS.length);
  const filled = Math.max(0, Math.min(value, slotCount));

  return (
    <div
      className={['health-bar', className].filter(Boolean).join(' ')}
      role="meter"
      aria-label="Здоровье"
      aria-valuemin={0}
      aria-valuemax={slotCount}
      aria-valuenow={filled}
    >
      {HEART_SLOTS.slice(0, slotCount).map((slot, index) => {
        const isFilled = index < filled;
        return (
          <div
            key={index}
            className="health-bar__slot"
            style={{
              left: slot.left,
              top: slot.top,
              width: HEART_WIDTH,
              height: HEART_HEIGHT,
            }}
          >
            <div className="health-bar__heart-wrap">
              <img
                className="health-bar__heart"
                src={isFilled ? heartImg : emptyHeartImg}
                alt=""
                draggable={false}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}
