export type PauseScreenProps = {
  onContinue?: () => void;
  onGoHome?: () => void;
  audioMuted?: boolean;
  onToggleMute?: () => void;
};

export type PauseScreenModel = {
  onContinue?: () => void;
  onGoHome?: () => void;
  audioMuted: boolean;
  onToggleMute?: () => void;
};

export function createPauseScreenModel(props: PauseScreenProps): PauseScreenModel {
  return {
    onContinue: props.onContinue,
    onGoHome: props.onGoHome,
    audioMuted: props.audioMuted ?? false,
    onToggleMute: props.onToggleMute,
  };
}
