import { useEffect, useRef, type Dispatch, type SetStateAction } from 'react';
import { tickRunnerPathObstaclesUseCase } from '../../../../../application/runner/runnerPathObstacleUseCases';
import { tickRunnerPathDecorsUseCase } from '../../../../../application/runner/runnerPathDecorUseCases';
import { tickRunnerLevelUseCase } from '../../../../../application/runner/runnerUseCases';
import type { CourierId } from '../../../../../domain/ids/ids';
import { hasRunnerReachedFinish } from '../../../../../domain/runner/runnerLevelRules';
import type { RunnerLevel, RunnerPlayer, VerticalMoveDirection } from '../../../../../domain/runner/runnerTypes';
import { RUNNER_MAX_DELTA_SECONDS } from '../../../../../domain/runner/runnerConstants';

export function useRunnerLevelTick(
  level: RunnerLevel | null,
  player: RunnerPlayer | null,
  setPlayer: Dispatch<SetStateAction<RunnerPlayer | null>>,
  setLevel: Dispatch<SetStateAction<RunnerLevel | null>>,
  courierId: CourierId,
  getVerticalDirection: () => VerticalMoveDirection,
  onFrame?: (deltaSeconds: number) => void,
  isPaused = false,
  getMotionScale: () => number = () => 1,
): void {
  const levelRef = useRef(level);
  levelRef.current = level;
  const playerRef = useRef(player);
  playerRef.current = player;
  const onFrameRef = useRef(onFrame);
  onFrameRef.current = onFrame;
  const isPausedRef = useRef(isPaused);
  isPausedRef.current = isPaused;
  const getMotionScaleRef = useRef(getMotionScale);
  getMotionScaleRef.current = getMotionScale;
  const getVerticalDirectionRef = useRef(getVerticalDirection);
  getVerticalDirectionRef.current = getVerticalDirection;
  const courierIdRef = useRef(courierId);
  courierIdRef.current = courierId;

  const sessionKey = level == null ? null : `${level.giantId}:${level.startPointSvgX}`;

  useEffect(() => {
    if (sessionKey == null) {
      return;
    }

    let frameId = 0;
    let lastTimestamp = performance.now();

    const tick = (timestamp: number): void => {
      if (isPausedRef.current) {
        lastTimestamp = timestamp;
        frameId = requestAnimationFrame(tick);
        return;
      }

      const currentLevel = levelRef.current;
      const current = playerRef.current;
      if (currentLevel == null) {
        frameId = requestAnimationFrame(tick);
        return;
      }

      const motionScale = getMotionScaleRef.current();
      if (
        current != null &&
        (current.lives <= 0 ||
          (motionScale <= 0 && hasRunnerReachedFinish(currentLevel, current)))
      ) {
        return;
      }

      const deltaSeconds = Math.min(
        (timestamp - lastTimestamp) / 1000,
        RUNNER_MAX_DELTA_SECONDS,
      );
      lastTimestamp = timestamp;

      const verticalDirection = getVerticalDirectionRef.current();
      onFrameRef.current?.(deltaSeconds);

      setPlayer((state) => {
        if (state == null) {
          return state;
        }
        if (state.lives <= 0) {
          return state;
        }
        const levelNow = levelRef.current;
        if (levelNow == null) {
          return state;
        }
        const scale = getMotionScaleRef.current();
        if (scale <= 0 && hasRunnerReachedFinish(levelNow, state)) {
          return state;
        }
        const next = tickRunnerLevelUseCase(
          levelNow,
          state,
          courierIdRef.current,
          verticalDirection,
          deltaSeconds,
          scale,
        );
        playerRef.current = next;
        return next;
      });

      setLevel((state) => {
        if (state == null) {
          return state;
        }
        const scale = getMotionScaleRef.current();
        let next = tickRunnerPathObstaclesUseCase(state, deltaSeconds, scale);
        next = tickRunnerPathDecorsUseCase(next, deltaSeconds, scale);
        if (next !== state) {
          levelRef.current = next;
        }
        return next;
      });

      frameId = requestAnimationFrame(tick);
    };

    frameId = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frameId);
    };
  }, [sessionKey, setPlayer, setLevel]);
}
