export type SelectCharacterScreenState = {
  selectedIndex: number;
  setSelectedIndex: Dispatch<SetStateAction<number>>;
};

export type SelectCharacterScreenModel = {
  selectedIndex: number;
  setSelectedIndex: Dispatch<SetStateAction<number>>;
  selectedCharacter: CharacterIconId;
  totalCharacters: number;
  nameLayout: {
    left: number;
    top: number;
    width: number;
    height: number;
    rotation: number;
  };
  stats: ReturnType<typeof getCharacterStats>;
  onConfirm?: (characterId: CharacterIconId) => void;
};

export function createSelectCharacterScreenModel(
  props: SelectCharacterScreenProps,
  state: SelectCharacterScreenState,
): SelectCharacterScreenModel {
  const selectedCharacter = CHARACTER_ORDER[state.selectedIndex] as CharacterIconId;

  return {
    selectedIndex: state.selectedIndex,
    setSelectedIndex: state.setSelectedIndex,
    selectedCharacter,
    totalCharacters: CHARACTER_ORDER.length,
    nameLayout: CHARACTER_NAMES_LAYOUT[selectedCharacter],
    stats: getCharacterStats(selectedCharacter),
    onConfirm: props.onConfirm,
  };
}
