import type { CSSProperties } from 'react';
import ticketImg from '../../icons/ticket/ticket.png';
import type { DeliveryUrgency } from '../../../../../../domain/economy/types';
import {
  getDeliveryPopupLayout,
  getDeliveryPopupSize,
  type DeliveryPopupTail,
} from './deliveryPopupLayout';
import { getDeliveryPopupMoodAssets } from './deliveryPopupMood';
import { DeliveryPopupMessage } from './DeliveryPopupMessage';
import { DeliveryPopupReward } from './DeliveryPopupReward';
import { TakeDeliveryButton } from './TakeDeliveryButton';
import './DeliveryPopup.css';

export type DeliveryPopupProps = {
  urgency: DeliveryUrgency;
  waitingDay: number;
  passReward: number;
  /** `up` — yetti/roza tail-up chrome (Figma 190:9422). */
  tail?: DeliveryPopupTail;
  onTakeOrder?: () => void;
  className?: string;
  style?: CSSProperties;
};

/** Figma delivery popup — default 180:347, tail-up 190:9422. */
export function DeliveryPopup({
  urgency,
  waitingDay,
  passReward,
  tail = 'down',
  onTakeOrder,
  className,
  style,
}: DeliveryPopupProps) {
  const mood = getDeliveryPopupMoodAssets(urgency, waitingDay, tail);
  const size = getDeliveryPopupSize(tail);
  const layout = getDeliveryPopupLayout(tail);
  const ticket = layout.ticketIcon;
  const button = layout.takeDeliveryButton;

  return (
    <div
      className={['delivery-popup', className].filter(Boolean).join(' ')}
      style={{
        width: size.width,
        height: size.height,
        ...style,
      }}
    >
      <img
        className="delivery-popup__background"
        src={mood.backgroundUrl}
        alt=""
        draggable={false}
        aria-hidden
      />
      <DeliveryPopupReward passReward={passReward} layout={layout.rewardAmount} />
      <div
        className="delivery-popup__ticket"
        style={{
          left: ticket.left,
          top: ticket.top,
          width: ticket.width,
          height: ticket.height,
        }}
      >
        <img
          className="delivery-popup__ticket-img"
          src={ticketImg}
          alt=""
          draggable={false}
          aria-hidden
          style={{ transform: `rotate(${ticket.rotateDeg}deg)` }}
        />
      </div>
      <DeliveryPopupMessage urgency={urgency} waitingDay={waitingDay} tail={tail} />
      <div
        className="delivery-popup__button-wrap"
        style={{
          left: button.left,
          top: button.top,
          width: button.width,
          height: button.height,
        }}
      >
        <TakeDeliveryButton onClick={onTakeOrder} />
      </div>
    </div>
  );
}
