import { getAudioService } from '../../infrastructure';
import { soundUrls, type SoundId } from './soundCatalog';

/** Load Howl instances for the sound catalog (soft-fail). */
export function preloadSounds(): void {
  if (process.env.NODE_ENV === 'test') {
    return;
  }
  try {
    getAudioService().loadCatalog(soundUrls);
  } catch (e) {
    console.warn('[presentation] sound preload failed', e);
  }
}

/** Play a catalog sound via the shared AudioService. */
export function playSound(id: SoundId, options?: { volume?: number }): void {
  getAudioService().play(id, options);
}

function pickVariant(a: SoundId, b: SoundId): SoundId {
  return Math.random() < 0.5 ? a : b;
}

/** Default UI click — arrows, back, generic buttons. */
export function playUiClick(): void {
  playSound('ui.click');
}

/** Hub / map chrome navigation (nav tabs, tickets, rating, player level). */
export function playUiClickB(): void {
  playSound('ui.click_b');
}

export function playUiInfo(): void {
  playSound('ui.info_b');
}

export function playDeliveryTake(): void {
  playSound('delivery.take');
}

export function playDeliverySuccess(): void {
  playSound('delivery.success');
}

export function playDeliveryFail(): void {
  playSound('delivery.fail');
}

export function playRunnerHit(): void {
  playSound(pickVariant('runner.hit', 'runner.hit_b'));
}

export function playRunnerSpark(): void {
  playSound(pickVariant('runner.spark', 'runner.spark_b'));
}

export function playRunnerBooster(): void {
  playSound(pickVariant('runner.booster', 'runner.booster_b'));
}

export function playRunnerFinish(): void {
  playSound('runner.finish');
}

/** Once after the loading screen completes at app start. */
export function playLoadingSfx(): void {
  playSound('loading.sfx');
}
