import '../components/atomic/layout/app_screen/app_screen.css';
import './level_screen.css';
import type { CharacterId } from '../../../domain/ids/ids';
import type { LevelScreenModel } from './LevelScreenModelScreen';
import { CollectibleProgress } from './collectible_progress/CollectibleProgress';
import { HealthBar } from './HealthBar';
import { LevelName } from './level_names/LevelName';
import { PauseButton } from './pause_button/PauseButton';
import { ProgressBar } from './progress_bar/ProgressBar';
import type { LevelScreenController } from './LevelScreenController';
import type { ScreenViewProps } from '../shared/screenViewProps';
import type { LevelRunSnapshot } from '../../store/settleLevelRun';
import { LevelGameplay } from './gameplay/LevelGameplay';

export type LevelScreenViewProps = ScreenViewProps<
  LevelScreenModel,
  LevelScreenController
> & {
  characterId: CharacterId;
  isPaused: boolean;
  onHudUpdate: (state: {
    health: number;
    maxHealth: number;
    collectiblesCollected: number;
    collectiblesTotal: number;
    progress: number;
  }) => void;
  onRunSnapshotUpdate?: (snapshot: LevelRunSnapshot) => void;
};

export function LevelScreenView({
  model,
  controller,
  characterId,
  isPaused,
  onHudUpdate,
  onRunSnapshotUpdate,
}: LevelScreenViewProps) {
  return (
    <div className="app-screen level-screen">
      <LevelGameplay
        giantId={model.giantId}
        orderIndex={model.orderIndex}
        characterId={characterId}
        isPaused={isPaused}
        onHudUpdate={onHudUpdate}
        onRunSnapshotUpdate={onRunSnapshotUpdate}
        onSuccess={(snapshot) => model.onSuccess?.(snapshot)}
        onFail={(snapshot) => model.onFail?.(snapshot)}
      />
      <LevelName id={model.giantId} orderIndex={model.orderIndex} />
      <ProgressBar value={model.progress} />
      <CollectibleProgress
        collected={model.collectiblesCollected}
        total={model.collectiblesTotal}
      />
      <HealthBar value={model.health} max={model.maxHealth} />
      <PauseButton onClick={controller.handlePause} />
    </div>
  );
}
