import './Lands.css';
import { isMapSectionColored } from '../../../../domain';
import { useAppStore } from '../../../store/appStore';
import { LAND_PLACEMENTS } from './landPositions';
import { LAND_IMAGES } from './mapLandAssets';
import { giantIdForLand } from './landGiantIds';

/**
 * Single wrapper for all map land/sea PNGs, placed by Figma Frame 2 coords.
 * Color when the land's giant was ever offered a delivery (sticky unlock).
 */
export function Lands() {
  const playerEconomy = useAppStore((s) => s.playerEconomy);

  return (
    <div className="map-lands" aria-hidden>
      {LAND_PLACEMENTS.map((land) => {
        const isColored = isMapSectionColored(playerEconomy, giantIdForLand(land.id));

        return (
          <img
            key={land.id}
            className={
              isColored
                ? 'map-lands__land'
                : 'map-lands__land map-lands__land--grayscale'
            }
            src={LAND_IMAGES[land.id]}
            alt=""
            draggable={false}
            style={{
              left: land.left,
              top: land.top,
              width: land.width,
              height: land.height,
            }}
          />
        );
      })}
    </div>
  );
}
