import bridge from '@vkontakte/vk-bridge';

type BridgeSend = (method: string, params?: Record<string, unknown>) => Promise<unknown>;

type OpenLinkEvent = {
  preventDefault: () => void;
};

/**
 * Open an external URL via VK bridge when embedded, otherwise rely on the
 * caller (e.g. `<a target="_blank">`) or `window.open` for programmatic calls.
 *
 * Important: outside VK, do not await a failing bridge call before `window.open` —
 * that loses the user-gesture context and the browser blocks the popup.
 * `VKWebAppOpenLink` is a client method; typings in @vkontakte/vk-bridge omit it.
 */
export async function openExternalLink(
  url: string,
  event?: OpenLinkEvent,
): Promise<void> {
  if (url === '') {
    return;
  }

  if (bridge.isEmbedded()) {
    event?.preventDefault();
    try {
      await (bridge.send as BridgeSend)('VKWebAppOpenLink', { url });
    } catch {
      window.open(url, '_blank', 'noopener,noreferrer');
    }
    return;
  }

  // Native <a target="_blank"> already opens the tab when `event` is present.
  if (event == null) {
    window.open(url, '_blank', 'noopener,noreferrer');
  }
}
