import './ScreenHeader.css';
import screenHeaderBackgroundImg from './screen_header_background.png';

type ScreenHeaderProps = {
  /** Visibility of sub_header_background (119:6978). Default: true. */
  showSubHeader?: boolean;
};

/** From Figma title_and_subtitle2 (119:6979) — sub_header + header image. */
export function ScreenHeader({ showSubHeader = true }: ScreenHeaderProps) {
  return (
    <div className="screen-header" aria-hidden>
      {showSubHeader ? <div className="screen-header__sub" /> : null}
      <img
        className="screen-header__main"
        src={screenHeaderBackgroundImg}
        alt=""
        draggable={false}
      />
    </div>
  );
}
