import type { CharacterId } from '../../../../domain/ids/ids';
import {
  RUNNER_PLAYER_SPRITE_HEIGHT_SVG,
  RUNNER_PLAYER_SPRITE_WIDTH_S,
  RUNNER_REF_VIEWBOX_WIDTH,
} from '../../../../domain/runner/runnerConstants';
import type { RunnerLevel, RunnerPlayer } from '../../../../domain/runner/runnerTypes';
import { runnerSpriteVariant } from '../../../../domain/runner/runnerPlayer';
import type { LevelCanvasLayout } from './layout/runnerLevelLayout';
import { projectSvgPointInWorld } from './layout/runnerLevelLayout';
import { LEVEL_GAMEPLAY_Z_INDEX, PLAYER_TILT_DEGREES } from './gameplayConstants';
import {
  getLevelCharacterSprite,
  getLevelCharacterSpriteAnchor,
  getLevelCharacterSpriteDisplayScale,
} from './characterLevelSprites';
import './LevelPlayerSprite.css';

type LevelPlayerSpriteProps = {
  level: RunnerLevel;
  player: RunnerPlayer;
  layout: LevelCanvasLayout;
  /** Наклон спрайта: -1..1 (доля от максимального угла). */
  tilt: number;
  characterId: CharacterId;
};

export function LevelPlayerSprite({
  level,
  player,
  layout,
  tilt,
  characterId,
}: LevelPlayerSpriteProps) {
  const svgX = level.startPointSvgX + player.worldS;
  const svgY = (1 - player.lane) * level.viewBox.height;
  const { leftPx, topPx } = projectSvgPointInWorld(svgX, svgY, layout);
  const variant = runnerSpriteVariant(player);
  const sprite = getLevelCharacterSprite(characterId, variant);
  const displayScale = getLevelCharacterSpriteDisplayScale(characterId, variant);
  const anchor = getLevelCharacterSpriteAnchor(characterId, variant);
  const scaleS = level.viewBox.width / RUNNER_REF_VIEWBOX_WIDTH;
  // Hitbox stays on RUNNER_PLAYER_SPRITE_*; only the drawn frame follows speed art size/anchor.
  const widthPx =
    RUNNER_PLAYER_SPRITE_WIDTH_S * scaleS * layout.displayScale * displayScale.scaleX;
  const heightPx =
    RUNNER_PLAYER_SPRITE_HEIGHT_SVG * scaleS * layout.displayScale * displayScale.scaleY;
  const tiltDeg = -tilt * PLAYER_TILT_DEGREES;
  const anchorXPct = anchor.x * 100;
  const anchorYPct = anchor.y * 100;

  return (
    <div
      className="level-player-sprite"
      style={{
        position: 'absolute',
        left: leftPx,
        top: topPx,
        width: widthPx,
        height: heightPx,
        transform: `translate(-${anchorXPct}%, -${anchorYPct}%)`,
        zIndex: LEVEL_GAMEPLAY_Z_INDEX.PLAYER,
      }}
    >
      <div
        className="level-player-sprite__inner"
        style={{
          transform: `rotate(${tiltDeg}deg)`,
          transformOrigin: `${anchorXPct}% ${anchorYPct}%`,
        }}
      >
        {sprite.showShieldShine ? (
          <img
            className="level-player-sprite__shine level-player-sprite__shine--pulse"
            src={sprite.shieldShineSrc}
            alt=""
            draggable={false}
          />
        ) : null}
        <img
          className="level-player-sprite__character"
          src={sprite.characterSrc}
          alt=""
          draggable={false}
        />
      </div>
    </div>
  );
}
