import '../components/atomic/layout/app_screen/app_screen.css';
import { Shine } from '../components/atomic/atmosphere/shine/Shine';
import { GoHomeButton } from '../components/atomic/buttons/go_home_button/GoHomeButton';
import { RestartButton } from '../components/atomic/buttons/restart_button/RestartButton';
import type { FailDeliveryScreenModel } from './FailDeliveryScreenModelScreen';
import { CharacterIcon } from './character_icon/CharacterIcon';
import { FailDeliveryClouds } from './clouds/FailDeliveryClouds';
import { FailDeliveryHeader } from './header/FailDeliveryHeader';
import { PlaqueSmallBad } from './plaque_small_bad/PlaqueSmallBad';
import type { FailDeliveryScreenController } from './FailDeliveryScreenController';
import './fail_delivery_screen.css';
import type { ScreenViewProps } from '../shared/screenViewProps';

export type FailDeliveryScreenViewProps = ScreenViewProps<
  FailDeliveryScreenModel,
  FailDeliveryScreenController
>;

/** Failed delivery screen stub (Figma game over screen 142:17524). */
export function FailDeliveryScreenView({
  model,
  controller,
}: FailDeliveryScreenViewProps) {
  return (
    <div className="app-screen fail-delivery-screen">
      <FailDeliveryClouds />
      <Shine variant="delivery" />
      <FailDeliveryHeader />
      <PlaqueSmallBad />
      <CharacterIcon characterId={model.characterId} />
      <RestartButton
        onClick={controller.handleRestart}
        cost={model.restartCost}
        disabled={!model.canRestart}
      />
      <GoHomeButton onClick={controller.handleGoHome} />
    </div>
  );
}
