import { useEffect, useMemo, useState } from 'react';
import { msUntilNextMoscowMidnight } from '../../../domain';
import { useAppStore } from '../../store/appStore';
import { getCurrentCourierLicenseLabel } from '../player_level_screen/courierLicenseLabels';
import {
  createMapScreenModel,
  INITIAL_CAMERA,
  type MapScreenProps,
} from './MapScreenModelScreen';
import { MapScreenController } from './MapScreenController';
import { MapScreenView } from './MapScreenView';

export type { MapScreenProps } from './MapScreenModelScreen';

export function MapScreen(props: MapScreenProps = {}) {
  useEffect(() => {
    void useAppStore.getState().refreshEconomy();
  }, []);

  useEffect(() => {
    function scheduleMidnightRefresh(): number {
      const msUntilMidnight = Math.max(1, msUntilNextMoscowMidnight(Date.now()));
      return window.setTimeout(() => {
        void useAppStore.getState().refreshEconomy();
        timerId = scheduleMidnightRefresh();
      }, msUntilMidnight);
    }

    let timerId = scheduleMidnightRefresh();
    return () => {
      window.clearTimeout(timerId);
    };
  }, []);

  const successfulDeliveries = useAppStore((s) => s.playerEconomy.ratedDeliveriesCount);
  const averageRating = useAppStore((s) => s.playerEconomy.totalRating);
  const lastRatingDelta = useAppStore((s) => s.lastRatingDelta);
  const playerLevelName = useMemo(
    () => getCurrentCourierLicenseLabel(successfulDeliveries, averageRating),
    [successfulDeliveries, averageRating],
  );

  const [camera, setCamera] = useState(INITIAL_CAMERA);
  const model = createMapScreenModel(
    { ...props, playerLevelName, averageRating, lastRatingDelta },
    { camera, setCamera },
  );
  const controller = new MapScreenController(model);

  return <MapScreenView model={model} controller={controller} />;
}
