import type { GiantId } from '../../../../domain/ids/ids';
import { GIANT_IDS } from '../../../../domain/ids/ids';
import type { DeliveryPopupTail } from '../../components/atomic/dialog/delivery_popups/deliveryPopupLayout';
import { MAP_HEIGHT, MAP_WIDTH } from '../lands/landPositions';

export type DeliveryPopupPlacement = {
  giantId: GiantId;
  left: number;
  top: number;
  /** Tail-up chrome (sol, mu, serj, yetti, roza). */
  tail?: DeliveryPopupTail;
};

/**
 * Positions from map.svg `#delivery_popups` groups,
 * scaled SVG (2222×1263) → world (9960×5662).
 * sol / mu / serj / yetti / roza: tail-up variant; everyone else: default down.
 */
export const DELIVERY_POPUP_PLACEMENTS: readonly DeliveryPopupPlacement[] = [
  { giantId: 'sol', left: 2904.626, top: 1676.712, tail: 'up' },
  { giantId: 'mu', left: 6900.295, top: 1950.173, tail: 'up' },
  { giantId: 'serj', left: 1196.814, top: 2568.323, tail: 'up' },
  { giantId: 'mona', left: 1174.401, top: 3147.705 },
  { giantId: 'duck', left: 1138.542, top: 4480.165 },
  { giantId: 'factor', left: 4796.22, top: 3268.809 },
  { giantId: 'drakochi', left: 7924.968, top: 3605.032 },
  { giantId: 'willy', left: 6300.147, top: 2190.276 },
  { giantId: 'yetti', left: 4625.887, top: 2859.717, tail: 'up' },
  { giantId: 'svami', left: 2800.941, top: 2406.482 },
  { giantId: 'roza', left: 8390.67, top: 2657.983, tail: 'up' },
] as const;

const PLACEMENT_BY_GIANT = new Map<GiantId, DeliveryPopupPlacement>(
  DELIVERY_POPUP_PLACEMENTS.map((placement) => [placement.giantId, placement]),
);

export function getDeliveryPopupPlacement(
  giantId: GiantId,
): DeliveryPopupPlacement | undefined {
  return PLACEMENT_BY_GIANT.get(giantId);
}

export function isDeliveryPopupPlacementInMapBounds(
  placement: DeliveryPopupPlacement,
): boolean {
  return (
    placement.left >= 0 &&
    placement.top >= 0 &&
    placement.left <= MAP_WIDTH &&
    placement.top <= MAP_HEIGHT
  );
}

export function allGiantIdsHaveDeliveryPopupPlacements(): boolean {
  return GIANT_IDS.every((giantId) => PLACEMENT_BY_GIANT.has(giantId));
}
