import './ProgressBar.css';
import finishFlagIcon from './finish_flag_icon.png';

/** Figma progress_bar_background (130:21296) — 139.8135 151.8711 800.3734×74.1494 */
const BAR_LEFT = 139.8135;
const BAR_TOP = 151.8711;
const BAR_WIDTH = 800.3734;
const BAR_HEIGHT = 74.1494;

/** Figma progress_bar_scale (130:21297) default width. */
const FIGMA_FILL_WIDTH = 289.3804;

/** finish_flag_icon — 922 100, asset 127×150 */
const FLAG_LEFT = 922;
const FLAG_TOP = 100;
const FLAG_WIDTH = 127;
const FLAG_HEIGHT = 150;

export type ProgressBarProps = {
  /** Progress 0–1. */
  value?: number;
  className?: string;
};

/** Figma progress HUD — track + fill + flag icon. */
export function ProgressBar({
  value = FIGMA_FILL_WIDTH / BAR_WIDTH,
  className,
}: ProgressBarProps) {
  const progress = Math.max(0, Math.min(1, value));
  const fillWidth = progress * BAR_WIDTH;

  return (
    <div
      className={['progress-bar', className].filter(Boolean).join(' ')}
      role="progressbar"
      aria-label="Прогресс уровня"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(progress * 100)}
    >
      <div
        className="progress-bar__bar"
        style={{
          left: BAR_LEFT,
          top: BAR_TOP,
          width: BAR_WIDTH,
          height: BAR_HEIGHT,
        }}
        aria-hidden
      >
        <div className="progress-bar__track">
          <div className="progress-bar__track-fill" />
          <div className="progress-bar__track-shade" />
        </div>
        {fillWidth > 0 ? (
          <div className="progress-bar__scale" style={{ width: fillWidth }}>
            <div className="progress-bar__scale-fill" />
            <div className="progress-bar__scale-shade" />
          </div>
        ) : null}
      </div>

      <img
        className="progress-bar__flag"
        src={finishFlagIcon}
        alt=""
        draggable={false}
        style={{
          left: FLAG_LEFT,
          top: FLAG_TOP,
          width: FLAG_WIDTH,
          height: FLAG_HEIGHT,
        }}
      />
    </div>
  );
}
