import backgroundImg from './background.png';
import failedTextImg from './failed_text.png';
import './FailedDelivery.css';

/**
 * From Figma failed_delivery (158:14790) — pink banner + «Провалена» label.
 * Screen position: 110.5 1293.84 859×179.85.
 */
export function FailedDelivery() {
  return (
    <div className="failed-delivery" aria-hidden>
      <img
        className="failed-delivery__background"
        src={backgroundImg}
        alt=""
        draggable={false}
      />
      <img
        className="failed-delivery__label"
        src={failedTextImg}
        alt="Провалена"
        draggable={false}
      />
    </div>
  );
}
