import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  getRunnerForwardSpeed,
  startRunnerLevelUseCase,
} from '../../../../application/runner/runnerUseCases';
import { buildRunnerLevelFromLayout } from '../../../../domain/runner/buildRunnerLevelFromLayout';
import type { RunnerLevel, RunnerPlayer, VerticalMoveDirection } from '../../../../domain/runner/runnerTypes';
import { getItemsLayoutForGiant } from '../../../../domain/level/giantItemsLayouts';
import type { CharacterId } from '../../../../domain/ids/ids';
import type { GiantId } from '../../../../domain/ids/ids';
import { VIEWPORT_WIDTH } from '../../../../domain/Constants';
import type { LevelRunSnapshot } from '../../../store/settleLevelRun';
import { playRunnerFinish } from '../../../assets/preloadSounds';
import {
  CAMERA_LEAD_EASE_MS,
  FINISH_DECEL_MS,
  LEVEL_COUNTDOWN_STEP_MS,
  LEVEL_COUNTDOWN_STEPS,
  LEVEL_PLAYFIELD_HEIGHT_PX,
} from './gameplayConstants';
import { LevelCountdownOverlay } from './LevelCountdownOverlay';
import { LevelPlayfield } from './LevelPlayfield';
import {
  computeStartCameraLeadS,
  createPlayfieldConfig,
} from './layout/runnerLevelLayout';
import { useRunnerCollisions } from './hooks/useRunnerCollisions';
import { useRunnerLevelTick } from './hooks/useRunnerLevelTick';
import { useHoldFlightInput } from './hooks/useHoldFlightInput';
import { smoothPlayerTilt } from './playerTilt';

const FINISH_DECEL_SEC = FINISH_DECEL_MS / 1000;
const CAMERA_LEAD_EASE_SEC = CAMERA_LEAD_EASE_MS / 1000;

function nextCountdownLabel(current: string): string | null {
  const index = LEVEL_COUNTDOWN_STEPS.indexOf(
    current as (typeof LEVEL_COUNTDOWN_STEPS)[number],
  );
  if (index < 0 || index >= LEVEL_COUNTDOWN_STEPS.length - 1) {
    return null;
  }
  return LEVEL_COUNTDOWN_STEPS[index + 1];
}

export type LevelGameplayProps = {
  giantId: GiantId;
  orderIndex: number;
  characterId: CharacterId;
  isPaused: boolean;
  onHudUpdate: (state: {
    health: number;
    maxHealth: number;
    collectiblesCollected: number;
    collectiblesTotal: number;
    progress: number;
  }) => void;
  onSuccess: (snapshot: LevelRunSnapshot) => void;
  onFail: (snapshot: LevelRunSnapshot) => void;
  onRunSnapshotUpdate?: (snapshot: LevelRunSnapshot) => void;
};

export function LevelGameplay({
  giantId,
  orderIndex,
  characterId,
  isPaused,
  onHudUpdate,
  onSuccess,
  onFail,
  onRunSnapshotUpdate,
}: LevelGameplayProps) {
  const layout = useMemo(
    () => getItemsLayoutForGiant(giantId, orderIndex),
    [giantId, orderIndex],
  );
  const [level, setLevel] = useState<RunnerLevel | null>(() =>
    buildRunnerLevelFromLayout(layout),
  );
  const [player, setPlayer] = useState<RunnerPlayer | null>(() => {
    const built = buildRunnerLevelFromLayout(layout);
    return startRunnerLevelUseCase(built, characterId).player;
  });
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [collectiblesCollected, setCollectiblesCollected] = useState(0);
  const [speedBoostersCollected, setSpeedBoostersCollected] = useState(0);
  const speedBoostersTotal = useMemo(
    () => layout.boosters.filter((booster) => booster.type === 'speed').length,
    [layout],
  );
  const [displayTilt, setDisplayTilt] = useState(0);
  const [isFinishing, setIsFinishing] = useState(false);
  const [countdownLabel, setCountdownLabel] = useState<string | null>(
    LEVEL_COUNTDOWN_STEPS[0],
  );
  const [cameraLeadS, setCameraLeadS] = useState(() => {
    const built = buildRunnerLevelFromLayout(layout);
    const session = startRunnerLevelUseCase(built, characterId);
    const playfield = createPlayfieldConfig(VIEWPORT_WIDTH, LEVEL_PLAYFIELD_HEIGHT_PX);
    return computeStartCameraLeadS(session.level, playfield, session.player);
  });
  const collisionCountRef = useRef(0);
  const prevLivesRef = useRef<number | null>(null);
  const levelRef = useRef(level);
  levelRef.current = level;
  const playerRef = useRef(player);
  playerRef.current = player;
  const motionScaleRef = useRef(1);
  const isFinishingRef = useRef(false);
  const finishElapsedRef = useRef(0);
  const finishTiltRef = useRef(0);
  const displayTiltRef = useRef(0);
  const cameraLeadSRef = useRef(cameraLeadS);
  const cameraLeadStartRef = useRef(cameraLeadS);
  const cameraLeadEaseElapsedRef = useRef(0);
  const finishReportedRef = useRef(false);
  const finishSoundPlayedRef = useRef(false);
  const failReportedRef = useRef(false);
  const onSuccessRef = useRef(onSuccess);
  onSuccessRef.current = onSuccess;
  const buildSnapshotRef = useRef<() => LevelRunSnapshot>(() => ({
    elapsedSec: 0,
    sparksCollected: 0,
    sparksTotal: 0,
    speedBoostersCollected: 0,
    speedBoostersTotal: 0,
    collisions: 0,
  }));

  useEffect(() => {
    const built = buildRunnerLevelFromLayout(layout);
    const session = startRunnerLevelUseCase(built, characterId);
    const playfield = createPlayfieldConfig(VIEWPORT_WIDTH, LEVEL_PLAYFIELD_HEIGHT_PX);
    const startLead = computeStartCameraLeadS(
      session.level,
      playfield,
      session.player,
    );
    setLevel(session.level);
    setPlayer(session.player);
    setElapsedSeconds(0);
    setCollectiblesCollected(0);
    setSpeedBoostersCollected(0);
    setDisplayTilt(0);
    setIsFinishing(false);
    setCountdownLabel(LEVEL_COUNTDOWN_STEPS[0]);
    setCameraLeadS(startLead);
    collisionCountRef.current = 0;
    prevLivesRef.current = session.player.lives;
    motionScaleRef.current = 1;
    isFinishingRef.current = false;
    finishElapsedRef.current = 0;
    finishTiltRef.current = 0;
    displayTiltRef.current = 0;
    cameraLeadSRef.current = startLead;
    cameraLeadStartRef.current = startLead;
    cameraLeadEaseElapsedRef.current = 0;
    finishReportedRef.current = false;
    finishSoundPlayedRef.current = false;
    failReportedRef.current = false;
  }, [layout, characterId, giantId, orderIndex]);

  const isCountingDown = countdownLabel != null;
  const motionFrozen = isPaused || isCountingDown;
  const inputEnabled = !motionFrozen && !isFinishing;

  useEffect(() => {
    if (countdownLabel == null || isPaused) {
      return;
    }
    const timerId = window.setTimeout(() => {
      setCountdownLabel((current) =>
        current == null ? null : nextCountdownLabel(current),
      );
    }, LEVEL_COUNTDOWN_STEP_MS);
    return () => {
      window.clearTimeout(timerId);
    };
  }, [countdownLabel, isPaused]);

  const { getVerticalDirection, playfieldPointerHandlers } = useHoldFlightInput({
    enabled: inputEnabled,
  });
  const getVerticalDirectionRef = useRef(getVerticalDirection);
  getVerticalDirectionRef.current = getVerticalDirection;

  const onSparksCollected = useCallback((count: number) => {
    setCollectiblesCollected((prev) => prev + count);
  }, []);
  const onSpeedBoostersCollected = useCallback((count: number) => {
    setSpeedBoostersCollected((prev) => prev + count);
  }, []);

  useRunnerCollisions(
    level,
    player,
    setLevel,
    setPlayer,
    onSparksCollected,
    onSpeedBoostersCollected,
  );

  const getMotionScale = useCallback(() => motionScaleRef.current, []);

  const getTickVerticalDirection = useCallback((): VerticalMoveDirection => {
    if (isFinishingRef.current) {
      return 0;
    }
    return getVerticalDirectionRef.current();
  }, []);

  const onFrame = useCallback((deltaSeconds: number) => {
    setElapsedSeconds((prev) => prev + deltaSeconds);

    const currentLevel = levelRef.current;
    const currentPlayer = playerRef.current;
    if (currentLevel == null || currentPlayer == null || currentPlayer.lives <= 0) {
      return;
    }

    if (cameraLeadSRef.current > 0) {
      cameraLeadEaseElapsedRef.current += deltaSeconds;
      const t = Math.min(
        1,
        cameraLeadEaseElapsedRef.current / CAMERA_LEAD_EASE_SEC,
      );
      const nextLead = cameraLeadStartRef.current * (1 - t);
      cameraLeadSRef.current = nextLead;
      setCameraLeadS(nextLead);
    }

    if (!isFinishingRef.current) {
      const speed = getRunnerForwardSpeed(currentLevel, currentPlayer);
      const remaining = currentLevel.routeEndS - currentPlayer.worldS;
      const brakingDistance = speed * FINISH_DECEL_SEC * 0.5;
      if (remaining <= brakingDistance) {
        isFinishingRef.current = true;
        finishElapsedRef.current = 0;
        finishTiltRef.current = displayTiltRef.current;
        if (!finishSoundPlayedRef.current) {
          finishSoundPlayedRef.current = true;
          playRunnerFinish();
        }
        setIsFinishing(true);
        setPlayer((state) =>
          state == null ? state : { ...state, targetLane: state.lane },
        );
      }
    }

    if (isFinishingRef.current) {
      finishElapsedRef.current += deltaSeconds;
      const t = Math.min(1, finishElapsedRef.current / FINISH_DECEL_SEC);
      const scale = 1 - t;
      motionScaleRef.current = scale;

      if (t >= 1 && !finishReportedRef.current) {
        finishReportedRef.current = true;
        setPlayer((state) => {
          if (state == null || currentLevel == null) {
            return state;
          }
          if (state.worldS >= currentLevel.routeEndS) {
            return state;
          }
          return { ...state, worldS: currentLevel.routeEndS };
        });
        onSuccessRef.current(buildSnapshotRef.current());
      }
    }

    const targetTilt = isFinishingRef.current
      ? finishTiltRef.current * motionScaleRef.current
      : getVerticalDirectionRef.current();
    const nextTilt = smoothPlayerTilt(
      displayTiltRef.current,
      targetTilt,
      deltaSeconds,
    );
    displayTiltRef.current = nextTilt;
    setDisplayTilt(nextTilt);
  }, []);

  useRunnerLevelTick(
    level,
    player,
    setPlayer,
    setLevel,
    characterId,
    getTickVerticalDirection,
    onFrame,
    motionFrozen,
    getMotionScale,
  );

  useEffect(() => {
    if (player == null) {
      return;
    }
    const prev = prevLivesRef.current;
    if (prev != null && player.lives < prev) {
      collisionCountRef.current += prev - player.lives;
    }
    prevLivesRef.current = player.lives;
  }, [player]);

  const buildSnapshot = useCallback((): LevelRunSnapshot => {
    return {
      elapsedSec: elapsedSeconds,
      sparksCollected: collectiblesCollected,
      sparksTotal: layout.sparks.length,
      speedBoostersCollected,
      speedBoostersTotal,
      collisions: collisionCountRef.current,
    };
  }, [
    collectiblesCollected,
    elapsedSeconds,
    layout.sparks.length,
    speedBoostersCollected,
    speedBoostersTotal,
  ]);
  buildSnapshotRef.current = buildSnapshot;

  useEffect(() => {
    onRunSnapshotUpdate?.(buildSnapshot());
  }, [buildSnapshot, onRunSnapshotUpdate]);

  useEffect(() => {
    if (level == null || player == null) {
      return;
    }
    const progress =
      level.routeEndS > 0 ? Math.min(1, player.worldS / level.routeEndS) : 0;
    onHudUpdate({
      health: player.lives,
      maxHealth: player.maxLives,
      collectiblesCollected,
      collectiblesTotal: layout.sparks.length,
      progress,
    });
  }, [
    level,
    player,
    collectiblesCollected,
    layout.sparks.length,
    onHudUpdate,
  ]);

  useEffect(() => {
    if (player != null && player.lives <= 0 && !failReportedRef.current) {
      failReportedRef.current = true;
      onFail(buildSnapshot());
    }
  }, [player, onFail, buildSnapshot]);

  if (level == null || player == null) {
    return null;
  }

  return (
    <>
      <LevelPlayfield
        giantId={giantId}
        level={level}
        player={player}
        tilt={displayTilt}
        characterId={characterId}
        cameraLeadS={cameraLeadS}
        pointerHandlers={playfieldPointerHandlers}
      />
      {countdownLabel != null ? (
        <LevelCountdownOverlay label={countdownLabel} />
      ) : null}
    </>
  );
}
