export function getDeliveryPopupMessage(
  messageId: DeliveryGiantMessageId,
  tail: DeliveryPopupTail = 'down',
): DeliveryPopupMessageSpec {
  const message = DELIVERY_POPUP_MESSAGES[messageId];
  if (tail !== 'up') {
    return message;
  }

  return {
    ...message,
    layout: {
      ...message.layout,
      left: message.layout.left + UP_MESSAGE_OFFSET.left,
      top: message.layout.top + UP_MESSAGE_OFFSET.top,
    },
  };
}

/** Mood-colored 4px outside stroke via text-shadow (no purple outer ring). */
export function buildDeliveryPopupMessageTextShadow(stroke: string): string {
  return filledStrokeShadow(stroke, 4);
}

function filledStrokeShadow(color: string, radius: number): string {
  const parts: string[] = [];
  for (let x = -radius; x <= radius; x++) {
    for (let y = -radius; y <= radius; y++) {
      if (x * x + y * y <= radius * radius) {
        parts.push(`${x}px ${y}px 0 ${color}`);
      }
    }
  }
  return parts.join(', ');
}
