import popupBackgroundImg from './popup_background.png';
import popupTextImg from './texts/popup_text.svg';
import './RewardPopup.css';

/** From Figma Group 1321317895 (142:17480) — reward speech bubble. */
export function RewardPopup() {
  return (
    <div className="sticker-reward-popup" role="status">
      <img
        className="sticker-reward-popup__background"
        src={popupBackgroundImg}
        alt=""
        draggable={false}
        aria-hidden
      />
      <img
        className="sticker-reward-popup__text"
        src={popupTextImg}
        alt="Самая быстрая доставка, которую я видела!"
        draggable={false}
      />
    </div>
  );
}
