import '../components/atomic/layout/app_screen/app_screen.css';
import { SunBeams } from '../components/atomic/atmosphere/sun_beams/SunBeams';
import { FrameHeader } from '../components/atomic/dialog/frame_header/FrameHeader';
import { SolidFrameBackground } from '../components/atomic/dialog/solid_frame_background/SolidFrameBackground';
import { SkyAtmosphere } from '../components/composite/atmosphere/sky_atmosphere/SkyAtmosphere';
import { QuizAnswerButton } from './answer_button/QuizAnswerButton';
import { QuizImage } from './content/QuizImage';
import { GoBackButton } from './go_back_button/GoBackButton';
import { Header } from './header/Header';
import type { QuizScreenController } from './QuizScreenController';
import { getQuizAnswerButtonState, type QuizScreenModel } from './QuizScreenModelScreen';
import { ClueLink } from './texts/ClueLink';
import { QuestionText } from './texts/QuestionText';
import './quiz_screen.css';
import type { ScreenViewProps } from '../shared/screenViewProps';

export type QuizScreenViewProps = ScreenViewProps<
  QuizScreenModel,
  QuizScreenController
>;

const QUIZ_COMPLETE_TEXT = 'Все вопросы пройдены!';

export function QuizScreenView({ model, controller }: QuizScreenViewProps) {
  const { question, feedback } = model;
  const answersLocked = feedback != null;

  return (
    <div className="app-screen quiz-screen">
      <SkyAtmosphere variant="welcome" />
      <SunBeams className="quiz-screen__sun-beams" />
      <SolidFrameBackground />
      <FrameHeader showSubHeader={false} />
      <Header />
      <QuizImage questionId={question?.id} />
      <QuestionText text={question?.prompt ?? QUIZ_COMPLETE_TEXT} />
      {question?.options.map((option, index) => {
        const slot = model.answerSlots[index];
        if (slot == null) {
          return null;
        }

        return (
          <QuizAnswerButton
            key={`${question.id}-${index}`}
            top={slot.top}
            label={option}
            state={getQuizAnswerButtonState(index, feedback)}
            disabled={answersLocked}
            onClick={() => controller.handleAnswer(index)}
          />
        );
      })}
      {question?.rutubeUrl ? (
        <ClueLink href={question.rutubeUrl} onClick={controller.handleClueClick} />
      ) : null}
      <GoBackButton onClick={controller.handleGoBack} />
    </div>
  );
}
