import { COURIER_IDS, type CourierId } from '../ids/ids';

/**
 * Мини-игры по курьеру (GDD «Мини-игры персонажей»).
 * Стабильные id для реестра UI / загрузки сцен (opaque strings из v1).
 * Ключи — CourierId v3.
 */
export const COURIER_MINIGAMES = {
  eddy: ['eddy_catch_phone', 'eddy_lucky_shot'],
  claudi: ['cloudy_sort_recipients', 'cloudy_sticker_parcels'],
  tuchi: ['tucci_melody_drakocha_yeti'],
  ufo: ['ufo_decipher_words', 'ufo_charge_batteries'],
  vall: ['vall_balance_load', 'vall_catch_parcels'],
  rock: ['rock_postamat_sort', 'rock_repair_gadget'],
} as const satisfies Record<CourierId, readonly string[]>;

export type MinigameId = (typeof COURIER_MINIGAMES)[CourierId][number];

export const ALL_MINIGAME_IDS: MinigameId[] = Array.from(
  new Set(COURIER_IDS.flatMap((c) => [...COURIER_MINIGAMES[c]])),
) as MinigameId[];

export function getMinigamesForCourier(courierId: CourierId): readonly MinigameId[] {
  return COURIER_MINIGAMES[courierId];
}

export function isMinigameId(value: string): value is MinigameId {
  return (ALL_MINIGAME_IDS as readonly string[]).includes(value);
}

export function isMinigameAllowedForCourier(
  courierId: CourierId,
  minigameId: MinigameId,
): boolean {
  return (COURIER_MINIGAMES[courierId] as readonly string[]).includes(minigameId);
}
