import {
  createSuccessDeliveryScreenModel,
  type SuccessDeliveryScreenProps,
} from './SuccessDeliveryScreenModelScreen';
import { SuccessDeliveryScreenController } from './SuccessDeliveryScreenController';
import { SuccessDeliveryScreenView } from './SuccessDeliveryScreenView';
import { usePlaySoundOnMount } from '../../hooks/usePlaySoundOnMount';

export type { SuccessDeliveryScreenProps } from './SuccessDeliveryScreenModelScreen';

export function SuccessDeliveryScreen(props: SuccessDeliveryScreenProps) {
  usePlaySoundOnMount('delivery.success');
  const model = createSuccessDeliveryScreenModel(props);
  const controller = new SuccessDeliveryScreenController(model);

  return <SuccessDeliveryScreenView model={model} controller={controller} />;
}
