/**
 * Giant icon layout on the delivery list card.
 *
 * Shared box for every giant — yetti AABB from concept1.svg,
 * relative to the delivery_card plaque (left 110.5, top 746).
 * Display uses object-fit: contain inside width×height so PNG aspect ratio is preserved.
 */
import { GIANT_IDS, type GiantId } from '../../../../../../domain/ids/ids';

export type DeliveryCardGiantLayout = {
  left: number;
  top: number;
  width: number;
  height: number;
  /** Mean of X/Y design÷png scales (layout AABB may differ from PNG aspect). */
  scale: number;
};

/** concept1.svg yetti — Absolute − plaque (110.5, 746). */
export const DELIVERY_CARD_GIANT_LAYOUT: DeliveryCardGiantLayout = {
  left: 99.58,
  top: 223.59,
  width: 195.52,
  height: 269.23,
  scale: 0.9992006866,
};

/** Same yetti box for every GiantId. */
export const DELIVERY_CARD_GIANT_LAYOUTS: Record<
  GiantId,
  DeliveryCardGiantLayout
> = Object.fromEntries(
  GIANT_IDS.map((id) => [id, DELIVERY_CARD_GIANT_LAYOUT]),
) as Record<GiantId, DeliveryCardGiantLayout>;

export function getDeliveryCardGiantLayout(
  _giantId: GiantId,
): DeliveryCardGiantLayout {
  return DELIVERY_CARD_GIANT_LAYOUT;
}
