import type {
  RunnerCyclicVisibilityMotion,
  RunnerDecorSprite,
  RunnerLevel,
  RunnerObstacle,
  RunnerRozaObstacleSpriteKey,
} from './runnerTypes';

/** Сколько препятствие видно за один цикл, сек. */
export const ROZA_OBSTACLE_VISIBLE_SEC = 2.2;

/** Сколько препятствие скрыто за один цикл, сек. */
export const ROZA_OBSTACLE_HIDDEN_SEC = 1.4;

/** Длительность fade-перехода на каждой границе фазы, сек. */
export const ROZA_OBSTACLE_FADE_SEC = 0.35;

/** Сдвиг старта цикла между объектами, чтобы не мигали синхронно. */
export const ROZA_OBSTACLE_STAGGER_SEC = 0.4;

type RozaObstacleDef = {
  id: string;
  spriteKey: RunnerRozaObstacleSpriteKey;
  /** Центр bbox path в roza/modif.svg (`<g id="1">`..`<g id="5">`). */
  centerSvgX: number;
  centerSvgY: number;
  widthSvg: number;
  heightSvg: number;
};

/** Позиции из roza/modif.svg: центры bbox групп `1`..`5` (без blur-паддинга фильтра). */
export const ROZA_OBSTACLE_DEFS: readonly RozaObstacleDef[] = [
  { id: 'roza_1', spriteKey: 'roza_1', centerSvgX: 5576.58, centerSvgY: 862.14, widthSvg: 315.79, heightSvg: 216.78 },
  { id: 'roza_2', spriteKey: 'roza_2', centerSvgX: 8085.76, centerSvgY: 167.94, widthSvg: 315.78, heightSvg: 216.78 },
  { id: 'roza_3', spriteKey: 'roza_3', centerSvgX: 6621.34, centerSvgY: 196.14, widthSvg: 2386.54, heightSvg: 623.89 },
  { id: 'roza_4', spriteKey: 'roza_4', centerSvgX: 7468.38, centerSvgY: 812.96, widthSvg: 2525.66, heightSvg: 611 },
  { id: 'roza_5', spriteKey: 'roza_5', centerSvgX: 6941.2, centerSvgY: 479.69, widthSvg: 2534.77, heightSvg: 1150.36 },
] as const;

/**
 * `#foam` из roza/modif.svg: raw rect `x=8305.73 y=1192.52 w=2514.34 h=1370.1`
 * с `transform="rotate(-180 8305.73 1192.52)"` (поворот вокруг собственного угла
 * зеркалит прямоугольник в противоположный квадрант).
 */
const ROZA_FOAM_SVG = {
  id: 'roza_foam',
  x: 5791.39,
  y: -177.58,
  width: 2514.34,
  height: 1370.1,
} as const;

function rozaSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function rozaSvgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

function initialCyclicMotion(index: number): RunnerCyclicVisibilityMotion {
  return {
    kind: 'cyclic',
    visibleSec: ROZA_OBSTACLE_VISIBLE_SEC,
    hiddenSec: ROZA_OBSTACLE_HIDDEN_SEC,
    fadeSec: ROZA_OBSTACLE_FADE_SEC,
    elapsedSec: -index * ROZA_OBSTACLE_STAGGER_SEC,
    phase: 'visible',
  };
}

/** Строит 5 неподвижных препятствий roza с цикличной видимостью, без коллизии. */
export function buildRozaModifierObstacles(level: RunnerLevel): RunnerObstacle[] {
  if (level.giantId !== 'roza') {
    return [];
  }
  const { startPointSvgX, viewBox } = level;
  return ROZA_OBSTACLE_DEFS.map((def, index) => {
    const centerS = rozaSvgXToS(def.centerSvgX, startPointSvgX);
    const centerLane = rozaSvgYToLane(def.centerSvgY, viewBox.height);
    return {
      id: def.id,
      anchorS: centerS,
      spriteKey: def.spriteKey,
      consumed: false,
      collides: false,
      opacity: 1,
      hitbox: {
        centerS,
        centerLane,
        widthS: def.widthSvg,
        heightLane: def.heightSvg / viewBox.height,
      },
      motion: initialCyclicMotion(index),
    };
  });
}

/** Foam roza: статичный неколлизионный декор поверх модификаторной зоны. */
export function buildRozaFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'roza') {
    return [];
  }
  const cx = ROZA_FOAM_SVG.x + ROZA_FOAM_SVG.width / 2;
  const cy = ROZA_FOAM_SVG.y + ROZA_FOAM_SVG.height / 2;
  return [
    {
      id: ROZA_FOAM_SVG.id,
      spriteKey: 'roza_foam',
      centerS: rozaSvgXToS(cx, level.startPointSvgX),
      centerLane: rozaSvgYToLane(cy, level.viewBox.height),
      widthS: ROZA_FOAM_SVG.width,
      heightLane: ROZA_FOAM_SVG.height / level.viewBox.height,
    },
  ];
}

export function hasActiveRozaModifierObstacles(level: RunnerLevel): boolean {
  const ids = new Set(ROZA_OBSTACLE_DEFS.map((d) => d.id));
  return level.obstacles.some((o) => ids.has(o.id));
}
