import type { RunnerDecorSprite, RunnerLevel, RunnerSolDecorSpriteKey } from './runnerTypes';

type SolDecorDef = {
  id: string;
  spriteKey: RunnerSolDecorSpriteKey;
  centerSvgX: number;
  centerSvgY: number;
  widthSvg: number;
  heightSvg: number;
};

/** Позиции из sol/modificators.svg: центры bbox групп `foam-1`..`foam-3` (raw rect, без blur-паддинга фильтра). */
const SOL_FOAM_DEFS: readonly SolDecorDef[] = [
  { id: 'sol_foam_1', spriteKey: 'sol_foam_1', centerSvgX: 6835.2, centerSvgY: 1017.81, widthSvg: 2194.52, heightSvg: 614.817 },
  { id: 'sol_foam_2', spriteKey: 'sol_foam_2', centerSvgX: 6835.2, centerSvgY: -88.22, widthSvg: 2194.52, heightSvg: 614.817 },
  { id: 'sol_foam_3', spriteKey: 'sol_foam_3', centerSvgX: 6836.2, centerSvgY: 500.76, widthSvg: 2460.48, heightSvg: 1431.34 },
] as const;

function solSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function solSvgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

function toDecorSprite(def: SolDecorDef, level: RunnerLevel): RunnerDecorSprite {
  return {
    id: def.id,
    spriteKey: def.spriteKey,
    centerS: solSvgXToS(def.centerSvgX, level.startPointSvgX),
    centerLane: solSvgYToLane(def.centerSvgY, level.viewBox.height),
    widthS: def.widthSvg,
    heightLane: def.heightSvg / level.viewBox.height,
    layer: 'front',
  };
}

/** Foam sol: статичный неколлизионный декор поверх игрока. */
export function buildSolFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'sol') {
    return [];
  }
  return SOL_FOAM_DEFS.map((def) => toDecorSprite(def, level));
}
