import starImg from '../../components/atomic/icons/star/star.png';
import { roundRating } from '../../../../domain';
import ratingTextImg from './rating_text.png';
import ratingValueBackgroundImg from './rating_value_background.png';
import ratingValueTextSvg from './rating_value_text.svg';
import './DeliveryRating.css';

/** Base star asset size from rating_screen icon_star (180.16×173.99). */
const STAR_BASE_WIDTH = 180.16;
const STAR_BASE_HEIGHT = 173.9908;
/** stars group frames (157:14729) — 111.28×107.47 / base ≈ 0.6177 */
const STAR_SCALE = 111.2766 / STAR_BASE_WIDTH;

const STARS = [
  { left: 193.6797, top: 137.0414 }, // 1
  { left: 261.9473, top: 136.9985 }, // 2
  { left: 336.2236, top: 136.9985 }, // 3
  { left: 410.5, top: 136.9985 }, // 4
  { left: 484.7764, top: 136.9985 }, // 5
] as const;

type DeliveryRatingProps = {
  rating?: number | null;
};

function formatDeliveryRatingLabel(rating: number): string {
  return `${roundRating(rating).toFixed(1).replace('.', ',')} из 5`;
}

/** Целое число звёзд на шкале 0–5 (3.5 → 3). */
function visibleStarCount(rating: number): number {
  return Math.min(5, Math.max(0, Math.floor(roundRating(rating))));
}

/**
 * From Figma Group 1321317896 (158:14774) — cream banner + value badge + stars.
 * Screen position: 110.5 1293.84 859×233.63.
 */
export function DeliveryRating({ rating }: DeliveryRatingProps) {
  const ratingLabel =
    rating != null && Number.isFinite(rating)
      ? formatDeliveryRatingLabel(rating)
      : null;
  const starCount =
    rating != null && Number.isFinite(rating) ? visibleStarCount(rating) : 0;

  return (
    <div className="delivery-rating" aria-hidden>
      <div className="delivery-rating__background" />
      <img
        className="delivery-rating__label"
        src={ratingTextImg}
        alt=""
        draggable={false}
      />
      <img
        className="delivery-rating__value-bg"
        src={ratingValueBackgroundImg}
        alt=""
        draggable={false}
      />
      {ratingLabel != null ? (
        <svg
          className="delivery-rating__value-text delivery-rating__value-text--live"
          width={164}
          height={73}
          viewBox="0 0 174 73"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          aria-hidden
        >
          <text
            className="delivery-rating__value-text-label"
            textAnchor="middle"
            xmlSpace="preserve"
            aria-live="polite"
          >
            <tspan x={87} y={48}>
              {ratingLabel}
            </tspan>
          </text>
        </svg>
      ) : (
        <img
          className="delivery-rating__value-text"
          src={ratingValueTextSvg}
          alt="3,8 из 5"
          draggable={false}
        />
      )}
      {STARS.slice(0, starCount).map((star, index) => (
        <img
          key={index}
          className="delivery-rating__star"
          src={starImg}
          alt=""
          draggable={false}
          style={{
            left: star.left,
            top: star.top,
            width: STAR_BASE_WIDTH * STAR_SCALE,
            height: STAR_BASE_HEIGHT * STAR_SCALE,
          }}
        />
      ))}
    </div>
  );
}
