import { useState } from 'react';
import {
  createSelectCharacterScreenModel,
  type SelectCharacterScreenProps,
} from './SelectCharacterScreenModelScreen';
import { SelectCharacterScreenController } from './SelectCharacterScreenController';
import { SelectCharacterScreenView } from './SelectCharacterScreenView';

export type { SelectCharacterScreenProps } from './SelectCharacterScreenModelScreen';

export function SelectCharacterScreen(props: SelectCharacterScreenProps = {}) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const model = createSelectCharacterScreenModel(props, {
    selectedIndex,
    setSelectedIndex,
  });
  const controller = new SelectCharacterScreenController(model);

  return <SelectCharacterScreenView model={model} controller={controller} />;
}
