import type { RunnerDecorSprite, RunnerLevel, RunnerObstacle } from './runnerTypes';

/** Диаметр мяча (одинаков для всех 6 — bbox path `#ball`/`#ball_2..6` в modificators.svg). */
const DUCK_BALL_DIAMETER_SVG = 359.15;

type DuckBallDef = {
  id: string;
  centerSvgX: number;
  centerSvgY: number;
};

/** Позиции мячей из duck/modificators.svg (`#ball`..`#ball_6`, центры bbox). */
export const DUCK_BALL_DEFS: readonly DuckBallDef[] = [
  { id: 'duck_ball_1', centerSvgX: 6100.84, centerSvgY: 707.98 },
  { id: 'duck_ball_2', centerSvgX: 7206.5, centerSvgY: 704.63 },
  { id: 'duck_ball_3', centerSvgX: 7301.16, centerSvgY: 130.92 },
  { id: 'duck_ball_4', centerSvgX: 6667.18, centerSvgY: 355.21 },
  { id: 'duck_ball_5', centerSvgX: 7768.7, centerSvgY: 482.58 },
  { id: 'duck_ball_6', centerSvgX: 6136.86, centerSvgY: 180.97 },
] as const;

/** Прямоугольник `#foam` из duck/modificators.svg (raw rect, без учёта blur-фильтра). */
const DUCK_FOAM_SVG = {
  id: 'duck_foam',
  x: 5581.4,
  y: -240.316,
  width: 2373.99,
  height: 1411.32,
} as const;

function duckSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function duckSvgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

/** Мячи duck: статичные, без коллизии, поверх игрока (layer: 'front'). */
export function buildDuckBallObstacles(level: RunnerLevel): RunnerObstacle[] {
  if (level.giantId !== 'duck') {
    return [];
  }
  const heightLane = DUCK_BALL_DIAMETER_SVG / level.viewBox.height;
  return DUCK_BALL_DEFS.map((def) => {
    const centerS = duckSvgXToS(def.centerSvgX, level.startPointSvgX);
    const centerLane = duckSvgYToLane(def.centerSvgY, level.viewBox.height);
    return {
      id: def.id,
      anchorS: centerS,
      spriteKey: 'duck_ball',
      layer: 'front',
      consumed: false,
      collides: false,
      hitbox: {
        centerS,
        centerLane,
        widthS: DUCK_BALL_DIAMETER_SVG,
        heightLane,
      },
    };
  });
}

/** Foam duck: статичный неколлизионный декор между игроком и мячами. */
export function buildDuckFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'duck') {
    return [];
  }
  const cx = DUCK_FOAM_SVG.x + DUCK_FOAM_SVG.width / 2;
  const cy = DUCK_FOAM_SVG.y + DUCK_FOAM_SVG.height / 2;
  return [
    {
      id: DUCK_FOAM_SVG.id,
      spriteKey: 'duck_foam',
      centerS: duckSvgXToS(cx, level.startPointSvgX),
      centerLane: duckSvgYToLane(cy, level.viewBox.height),
      widthS: DUCK_FOAM_SVG.width,
      heightLane: DUCK_FOAM_SVG.height / level.viewBox.height,
      layer: 'front',
    },
  ];
}
