export function muSvgYToLane(absoluteSvgY: number): number {
  const localY = absoluteSvgY - MU_PLAY_STRIP_OFFSET_Y;
  return 1 - localY / MU_PLAY_STRIP_HEIGHT;
}

export function muSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function hitboxAt(
  centerS: number,
  centerLane: number,
  widthSvg: number,
  heightSvg: number,
): RunnerHitbox {
  return {
    centerS,
    centerLane,
    widthS: widthSvg,
    heightLane: heightSvg / MU_PLAY_STRIP_HEIGHT,
  };
}

export function buildMuMeteorObstacles(level: RunnerLevel): RunnerObstacle[] {
  const { startPointSvgX } = level;
  return MU_METEOR_PATHS.map((path) => {
    const startS = muSvgXToS(path.startSvgX, startPointSvgX);
    const startLane = muSvgYToLane(path.startSvgY);
    const finishS = muSvgXToS(path.finishSvgX, startPointSvgX);
    const finishLane = muSvgYToLane(path.finishSvgY);
    return {
      id: path.id,
      anchorS: startS,
      spriteKey: path.spriteKey,
      hitbox: hitboxAt(startS, startLane, path.widthSvg, path.heightSvg),
      consumed: false,
      motion: {
        kind: 'path',
        startS,
        startLane,
        finishS,
        finishLane,
        durationSec: MU_METEOR_FLIGHT_DURATION_SEC,
        elapsedSec: 0,
      },
    };
  });
}

export function hasActiveMuMeteorObstacles(level: RunnerLevel): boolean {
  const ids = new Set(MU_METEOR_PATHS.map((p) => p.id));
  return level.obstacles.some((o) => ids.has(o.id) && !o.consumed);
}
