import iconTicketSvg from './icon_ticket.svg';
import './TicketReward.css';

export type TicketRewardProps = {
  rewardPasses: number;
};

/** Figma icon_ticket + dynamic «+N» text — ticket reward in header. */
export function TicketReward({ rewardPasses }: TicketRewardProps) {
  return (
    <div className="daily-strike-ticket-reward" aria-hidden>
      <span className="daily-strike-ticket-reward__badge">+{rewardPasses}</span>
      <img
        className="daily-strike-ticket-reward__icon"
        src={iconTicketSvg}
        alt=""
        draggable={false}
      />
    </div>
  );
}
