import { playDeliveryTake, playUiClickB } from '../../assets/preloadSounds';
import type { ArrowDirection } from '../components/atomic/buttons/arrows/Arrows';
import type { NavBarTab } from '../components/composite/nav/nav_bar/NavBar';
import type { GiantId } from './giants/giantPositions';
import {
  clampCamera,
  MAP_SCREEN_WORLD,
  type MapCamera,
  type MapScreenModel,
} from './MapScreenModelScreen';

export class MapScreenController {
  constructor(private readonly model: MapScreenModel) {}

  handleNavigate = (direction: ArrowDirection) => {
    this.model.setCamera((prev) => {
      let { x, y } = prev;

      switch (direction) {
        case 'left':
          x -= MAP_SCREEN_WORLD.panStep;
          break;
        case 'right':
          x += MAP_SCREEN_WORLD.panStep;
          break;
        case 'up':
          y -= MAP_SCREEN_WORLD.panStep;
          break;
        case 'down':
          y += MAP_SCREEN_WORLD.panStep;
          break;
      }

      return clampCamera({ ...prev, x, y });
    });
  };

  handlePan = (camera: MapCamera) => {
    this.model.setCamera(clampCamera(camera));
  };

  handleTabChange = (tab: NavBarTab) => {
    this.model.onTabChange?.(tab);
  };

  handleTakeDelivery = (giantId: GiantId, orderIndex: number) => {
    playDeliveryTake();
    this.model.onTakeDelivery?.(giantId, orderIndex);
  };

  handleOpenTickets = () => {
    playUiClickB();
    this.model.onOpenTickets?.();
  };

  handleOpenRating = () => {
    playUiClickB();
    this.model.onOpenRating?.();
  };

  handleOpenPlayerLevel = () => {
    playUiClickB();
    this.model.onOpenPlayerLevel?.();
  };
}
