import { useEffect, useState, type ReactNode } from 'react';
import './App.css';
import { VIEWPORT_HEIGHT, VIEWPORT_WIDTH } from './domain/Constants';
import { computeFitScale } from './infrastructure/runtime/fitViewport';
import { useAudioUnlock } from './presentation/hooks/useAudioUnlock';
import { ScreenCoordinator } from './presentation/navigation/ScreenCoordinator';
import { useAppStore } from './presentation/store/appStore';

function useFitScale() {
  const [scale, setScale] = useState(() => computeFitScale());

  useEffect(() => {
    const update = () => setScale(computeFitScale());

    update();
    window.addEventListener('resize', update);
    window.visualViewport?.addEventListener('resize', update);
    return () => {
      window.removeEventListener('resize', update);
      window.visualViewport?.removeEventListener('resize', update);
    };
  }, []);

  return scale;
}

function AppShell({ children }: { children: ReactNode }) {
  const scale = useFitScale();
  useAudioUnlock();

  return (
    <div
      className="App-shell"
      style={{
        width: VIEWPORT_WIDTH * scale.x,
        height: VIEWPORT_HEIGHT * scale.y,
      }}
    >
      <div
        className="App"
        style={{
          width: VIEWPORT_WIDTH,
          height: VIEWPORT_HEIGHT,
          transform: `scale(${scale.x}, ${scale.y})`,
        }}
      >
        {children}
      </div>
    </div>
  );
}

function App() {
  const hydrationStatus = useAppStore((s) => s.hydrationStatus);
  const hydrationError = useAppStore((s) => s.hydrationError);

  useEffect(() => {
    void useAppStore.getState().bootstrap();
  }, []);

  if (hydrationStatus === 'error') {
    return (
      <AppShell>
        <div className="App-bootstrap App-bootstrap--error">
          <p>Не удалось загрузить прогресс.</p>
          {hydrationError ? <p className="App-bootstrap__detail">{hydrationError}</p> : null}
          <button
            type="button"
            className="App-bootstrap__retry"
            onClick={() => void useAppStore.getState().bootstrap()}
          >
            Повторить
          </button>
        </div>
      </AppShell>
    );
  }

  if (hydrationStatus === 'loading') {
    return (
      <AppShell>
        <div className="App-bootstrap App-bootstrap--loading">Загрузка…</div>
      </AppShell>
    );
  }

  return (
    <AppShell>
      <ScreenCoordinator />
    </AppShell>
  );
}

export default App;
