import './StickerItem.css';

export type StickerItemLayout = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export type StickerItemProps = {
  iconSrc: string;
  iconLayout: StickerItemLayout;
  ariaLabel: string;
  isUnlocked?: boolean;
  onClick?: () => void;
};

/** One sticker icon (Figma s_1…g_5 slots). */
export function StickerItem({
  iconSrc,
  iconLayout,
  ariaLabel,
  isUnlocked = true,
  onClick,
}: StickerItemProps) {
  return (
    <div
      className="sticker-item"
      aria-label={ariaLabel}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      onClick={onClick}
      onKeyDown={
        onClick
          ? (event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                onClick();
              }
            }
          : undefined
      }
    >
      <img
        className={
          isUnlocked
            ? 'sticker-item__icon'
            : 'sticker-item__icon sticker-item__icon--locked'
        }
        src={iconSrc}
        alt=""
        draggable={false}
        aria-hidden
        style={{
          left: iconLayout.left,
          top: iconLayout.top,
          width: iconLayout.width,
          height: iconLayout.height,
        }}
      />
    </div>
  );
}
