import type { CharacterId } from '../../../../domain/ids/ids';
import type { BoosterKind } from '../../../../domain/catalog/boosters';
import claudiBase from '../../components/atomic/character/characters_image/claudi.png';
import eddyBase from '../../components/atomic/character/characters_image/eddy.png';
import rockBase from '../../components/atomic/character/characters_image/rock.png';
import tuchiBase from '../../components/atomic/character/characters_image/tuchi.png';
import ufoBase from '../../components/atomic/character/characters_image/ufo.png';
import vallBase from '../../components/atomic/character/characters_image/vall.png';
import claudiSpeed from '../../components/atomic/character/speed_booster_character_images/claudi.png';
import eddySpeed from '../../components/atomic/character/speed_booster_character_images/eddy.png';
import rockSpeed from '../../components/atomic/character/speed_booster_character_images/rock.png';
import tuchiSpeed from '../../components/atomic/character/speed_booster_character_images/tuchi.png';
import ufoSpeed from '../../components/atomic/character/speed_booster_character_images/ufo.png';
import vallSpeed from '../../components/atomic/character/speed_booster_character_images/vall.png';
import shieldShine from '../../components/atomic/character/shield_booster_shine/shield_booster_shine.png';

export type LevelCharacterSpriteVariant = 'normal' | BoosterKind | 'shield';

const BASE_BY_ID: Record<CharacterId, string> = {
  claudi: claudiBase,
  eddy: eddyBase,
  rock: rockBase,
  tuchi: tuchiBase,
  ufo: ufoBase,
  vall: vallBase,
};

const SPEED_BY_ID: Record<CharacterId, string> = {
  claudi: claudiSpeed,
  eddy: eddySpeed,
  rock: rockSpeed,
  tuchi: tuchiSpeed,
  ufo: ufoSpeed,
  vall: vallSpeed,
};

export type LevelCharacterSprite = {
  characterSrc: string;
  showShieldShine: boolean;
  shieldShineSrc: string;
};

/** Intrinsic PNG sizes — used to keep on-screen character scale when swapping to speed art. */
type SpriteIntrinsicSize = { width: number; height: number };

const BASE_SIZE_BY_ID: Record<CharacterId, SpriteIntrinsicSize> = {
  claudi: { width: 255, height: 220 },
  eddy: { width: 217, height: 161 },
  rock: { width: 229, height: 415 },
  tuchi: { width: 152, height: 275 },
  ufo: { width: 240, height: 254 },
  vall: { width: 394, height: 258 },
};

const SPEED_SIZE_BY_ID: Record<CharacterId, SpriteIntrinsicSize> = {
  claudi: { width: 468, height: 278 },
  eddy: { width: 455, height: 254 },
  rock: { width: 245, height: 397 },
  tuchi: { width: 449, height: 306 },
  ufo: { width: 366, height: 286 },
  vall: { width: 366, height: 298 },
};

/**
 * Point inside the speed sprite (0–1) that should sit on the hitbox center.
 * Trails are usually on the left, so X > 0.5 keeps the body aligned.
 * Tune per character if art alignment drifts.
 */
const SPEED_ANCHOR_BY_ID: Record<CharacterId, { x: number; y: number }> = {
  claudi: { x: 0.73, y: 0.5 },
  eddy: { x: 0.76, y: 0.48 },
  rock: { x: 0.58, y: 0.48 },
  tuchi: { x: 0.78, y: 0.45 },
  ufo: { x: 0.68, y: 0.5 },
  vall: { x: 0.62, y: 0.52 },
};

const CENTER_ANCHOR = { x: 0.5, y: 0.5 };

export function getAllLevelCharacterSpriteUrls(): string[] {
  const urls = [shieldShine];
  for (const id of Object.keys(BASE_BY_ID) as CharacterId[]) {
    urls.push(BASE_BY_ID[id], SPEED_BY_ID[id]);
  }
  return urls;
}

/**
 * Display-box scale relative to the normal player sprite frame.
 * Hitbox stays on RUNNER_PLAYER_SPRITE_* — only the drawn img container uses this.
 * For speed art, scales by speed/base intrinsic size so object-fit:contain keeps the same px scale.
 */
export function getLevelCharacterSpriteDisplayScale(
  characterId: CharacterId,
  variant: LevelCharacterSpriteVariant,
): { scaleX: number; scaleY: number } {
  if (variant !== 'speed') {
    return { scaleX: 1, scaleY: 1 };
  }
  const base = BASE_SIZE_BY_ID[characterId];
  const speed = SPEED_SIZE_BY_ID[characterId];
  return {
    scaleX: speed.width / base.width,
    scaleY: speed.height / base.height,
  };
}

/** Anchor inside the drawn sprite box (0–1). Hitbox center stays fixed; only the image shifts. */
export function getLevelCharacterSpriteAnchor(
  characterId: CharacterId,
  variant: LevelCharacterSpriteVariant,
): { x: number; y: number } {
  if (variant !== 'speed') {
    return CENTER_ANCHOR;
  }
  return SPEED_ANCHOR_BY_ID[characterId];
}

export function getLevelCharacterSprite(
  characterId: CharacterId,
  variant: LevelCharacterSpriteVariant,
): LevelCharacterSprite {
  if (variant === 'speed') {
    return {
      characterSrc: SPEED_BY_ID[characterId],
      showShieldShine: false,
      shieldShineSrc: shieldShine,
    };
  }
  return {
    characterSrc: BASE_BY_ID[characterId],
    showShieldShine: variant === 'shield',
    shieldShineSrc: shieldShine,
  };
}
