import { useCallback, useEffect, useState } from 'react';
import { ensureGiantLevelAssets } from '../../assets/preloadSessionLevelAssets';
import {
  beginLevelAttempt,
  updateActiveLevelSnapshot,
} from '../../store/levelRunSession';
import type { LevelRunSnapshot } from '../../store/settleLevelRun';
import {
  createLevelScreenModel,
  type LevelScreenProps,
} from './LevelScreenModelScreen';
import { LevelScreenController } from './LevelScreenController';
import { LevelScreenView } from './LevelScreenView';

export type { LevelScreenProps } from './LevelScreenModelScreen';

export function LevelScreen(props: LevelScreenProps) {
  const giantId = props.giantId ?? 'mona';
  const orderIndex = props.orderIndex ?? 0;
  const levelKey = props.levelKey ?? 0;
  const [levelAssetsReady, setLevelAssetsReady] = useState(false);

  useEffect(() => {
    beginLevelAttempt(giantId, orderIndex, levelKey);
  }, [giantId, orderIndex, levelKey]);

  useEffect(() => {
    let cancelled = false;
    setLevelAssetsReady(false);
    void ensureGiantLevelAssets(giantId).then(() => {
      if (!cancelled) {
        setLevelAssetsReady(true);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [giantId, levelKey]);

  const [hud, setHud] = useState({
    health: props.health ?? 5,
    maxHealth: props.maxHealth ?? 5,
    collectiblesCollected: props.collectiblesCollected ?? 0,
    collectiblesTotal: props.collectiblesTotal ?? 0,
    progress: props.progress ?? 0,
  });

  const onHudUpdate = useCallback(
    (next: {
      health: number;
      maxHealth: number;
      collectiblesCollected: number;
      collectiblesTotal: number;
      progress: number;
    }) => {
      setHud(next);
    },
    [],
  );

  const onRunSnapshotUpdate = useCallback((snapshot: LevelRunSnapshot) => {
    updateActiveLevelSnapshot(snapshot);
  }, []);

  const model = createLevelScreenModel({
    ...props,
    ...hud,
  });
  const controller = new LevelScreenController(model);

  if (!levelAssetsReady) {
    return null;
  }

  return (
    <LevelScreenView
      model={model}
      controller={controller}
      characterId={props.characterId ?? 'eddy'}
      isPaused={props.isPaused ?? false}
      onHudUpdate={onHudUpdate}
      onRunSnapshotUpdate={onRunSnapshotUpdate}
    />
  );
}
