import { COURIER_SCREEN_X_RATIO } from '../../../../../domain/catalog/flightPhysics';
import { RUNNER_LANE_MAX } from '../../../../../domain/runner/runnerConstants';
import type { RunnerLevel, RunnerPlayer } from '../../../../../domain/runner/runnerTypes';

export type LevelCanvasLayout = {
  canvasLeftPx: number;
  canvasTopPx: number;
  canvasWidthPx: number;
  canvasHeightPx: number;
  contentOffsetPx: number;
  displayScale: number;
};

export type PlayfieldConfig = {
  widthPx: number;
  heightPx: number;
  courierScreenX: number;
};

export function createPlayfieldConfig(widthPx: number, heightPx: number): PlayfieldConfig {
  return {
    widthPx,
    heightPx,
    courierScreenX: widthPx * COURIER_SCREEN_X_RATIO,
  };
}

function computeDisplayScale(playfieldHeightPx: number, viewBoxHeight: number): number {
  if (viewBoxHeight <= 0 || playfieldHeightPx <= 0) {
    return 1;
  }
  return playfieldHeightPx / viewBoxHeight;
}

/**
 * Минимальный lead (в единицах route s), чтобы левый край мира
 * не был правее 0 во вьюпорте при текущем worldS.
 */
export function computeStartCameraLeadS(
  level: RunnerLevel,
  playfield: PlayfieldConfig,
  player: RunnerPlayer,
): number {
  const displayScale = computeDisplayScale(playfield.heightPx, level.viewBox.height);
  if (displayScale <= 0) {
    return 0;
  }
  // worldLeft = courierScreenX - (worldS + lead + spawnSvgX) * scale
  // worldLeft <= 0  ⇒  lead >= courierScreenX / scale - worldS - spawnSvgX
  const lead =
    playfield.courierScreenX / displayScale - player.worldS - level.spawnSvgX;
  return Math.max(0, lead);
}

export function computeRunnerLevelLayout(
  level: RunnerLevel,
  playfield: PlayfieldConfig,
  player: RunnerPlayer,
  cameraLeadS = 0,
): LevelCanvasLayout {
  const displayScale = computeDisplayScale(playfield.heightPx, level.viewBox.height);
  return {
    canvasLeftPx:
      playfield.courierScreenX - (player.worldS + cameraLeadS) * displayScale,
    canvasTopPx: 0,
    canvasWidthPx: level.viewBox.width * displayScale,
    canvasHeightPx: playfield.heightPx,
    contentOffsetPx: -level.spawnSvgX * displayScale,
    displayScale,
  };
}

export function computeRunnerFallbackLayout(
  level: RunnerLevel,
  playfield: PlayfieldConfig,
): LevelCanvasLayout {
  const displayScale = computeDisplayScale(playfield.heightPx, level.viewBox.height);
  return {
    canvasLeftPx: playfield.courierScreenX,
    canvasTopPx: 0,
    canvasWidthPx: level.viewBox.width * displayScale,
    canvasHeightPx: playfield.heightPx,
    contentOffsetPx: -level.spawnSvgX * displayScale,
    displayScale,
  };
}

export type PlayerScreenPosition = {
  leftPx: number;
  topPx: number;
};

export function projectRunnerPlayerToScreen(
  level: RunnerLevel,
  player: RunnerPlayer,
  layout: LevelCanvasLayout,
): PlayerScreenPosition {
  const svgX = level.startPointSvgX + player.worldS;
  const svgY = (RUNNER_LANE_MAX - player.lane) * level.viewBox.height;
  return {
    leftPx: layout.canvasLeftPx + svgX * layout.displayScale + layout.contentOffsetPx,
    topPx: layout.canvasTopPx + svgY * layout.displayScale,
  };
}

export function projectSvgPointToScreen(
  svgX: number,
  svgY: number,
  layout: LevelCanvasLayout,
): PlayerScreenPosition {
  return {
    leftPx: layout.canvasLeftPx + svgX * layout.displayScale + layout.contentOffsetPx,
    topPx: layout.canvasTopPx + svgY * layout.displayScale,
  };
}

/** Координаты внутри `.level-playfield__world` (уже со сдвигом камеры). */
export function projectSvgPointInWorld(
  svgX: number,
  svgY: number,
  layout: LevelCanvasLayout,
): PlayerScreenPosition {
  return {
    leftPx: svgX * layout.displayScale,
    topPx: svgY * layout.displayScale,
  };
}
