import {
  RUNNER_PLAYER_SPRITE_HEIGHT_SVG,
  RUNNER_PLAYER_SPRITE_WIDTH_S,
  RUNNER_REF_VIEWBOX_WIDTH,
} from './runnerConstants';
import type { RunnerHitbox, RunnerLevel, RunnerPlayer } from './runnerTypes';

function spriteScaleS(viewBoxWidth: number): number {
  return viewBoxWidth / RUNNER_REF_VIEWBOX_WIDTH;
}

export function computeRunnerPlayerHitbox(level: RunnerLevel, player: RunnerPlayer): RunnerHitbox {
  const scaleS = spriteScaleS(level.viewBox.width);
  return {
    centerS: player.worldS,
    centerLane: player.lane,
    widthS: RUNNER_PLAYER_SPRITE_WIDTH_S * scaleS,
    heightLane: RUNNER_PLAYER_SPRITE_HEIGHT_SVG / level.viewBox.height,
  };
}
