import type { CSSProperties, ReactNode } from 'react';
import './NavBarButton.css';

export type NavBarButtonProps = {
  active?: boolean;
  onClick?: () => void;
  className?: string;
  style?: CSSProperties;
  'aria-label'?: string;
  children?: ReactNode;
};

/**
 * Figma nav tab background:
 * - inactive `menu` (104:25593) — 360×240, solid #b8a1cd
 * - active `Rectangle 352` (104:25606) — 360×255, radial #dfc3de → #b8a1cd
 * Shared: border 8 #675b9d, radius 25 25 0 0, inset bevels 21px.
 *
 * Surface is a child so icon coordinates match the Figma outer box (360×H).
 */
export function NavBarButton({
  active = false,
  onClick,
  className,
  style,
  'aria-label': ariaLabel,
  children,
}: NavBarButtonProps) {
  const classes = [
    'nav-bar-button',
    active ? 'nav-bar-button--active' : '',
    className ?? '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button
      type="button"
      className={classes}
      style={style}
      aria-label={ariaLabel}
      aria-pressed={active}
      onClick={onClick}
    >
      <span className="nav-bar-button__surface" aria-hidden />
      {children}
    </button>
  );
}
