import type { ArrowDirection } from '../components/atomic/buttons/arrows/Arrows';
import type { NavBarTab } from '../components/composite/nav/nav_bar/NavBar';
import {
  closeInfoPopup,
  toggleInfoPopup,
} from '../shared/infoPopup/infoPopupControllerActions';
import { nextPageForDirection } from '../shared/pagination/clampPageChange';
import type { DeliveryListScreenModel } from './DeliveryListScreenModelScreen';

export class DeliveryListScreenController {
  constructor(private readonly model: DeliveryListScreenModel) {}

  handleNavigate = (direction: ArrowDirection) => {
    if (!this.model.hasDeliveries) {
      return;
    }
    const maxIndex = Math.max(0, this.model.deliveryCount - 1);
    this.model.setSelectedIndex((current) =>
      nextPageForDirection(direction, current, maxIndex),
    );
    this.model.onNavigate?.(direction);
  };

  handleInfoButtonClick = () => {
    toggleInfoPopup(this.model);
  };

  handleInfoClose = () => {
    closeInfoPopup(this.model);
  };

  handleTabChange = (tab: NavBarTab) => {
    this.model.onTabChange?.(tab);
  };

  handleCardClick = () => {
    if (!this.model.hasDeliveries) {
      return;
    }
    this.model.onOpenDelivery?.(
      this.model.giantId,
      this.model.orderIndex,
      this.model.revealItem,
    );
  };
}
