import { useState } from 'react';
import './Giants.css';
import { isMapSectionColored } from '../../../../domain';
import { useAppStore } from '../../../store/appStore';
import { GIANT_PLACEMENTS, type GiantId } from './giantPositions';
import { MAP_GIANT_IMAGES } from './mapGiantAssets';

/**
 * Map giants in Frame 2 design coords (same world / MAP_SCALE as lands).
 * Color when the giant was ever offered a delivery (sticky unlock).
 */
export function Giants({
  onGiantClick,
}: {
  onGiantClick?: (giantId: GiantId) => void;
}) {
  const [pressedId, setPressedId] = useState<GiantId | null>(null);
  const playerEconomy = useAppStore((s) => s.playerEconomy);

  return (
    <div className="map-giants">
      {GIANT_PLACEMENTS.map((giant) => {
        const imageSrc = MAP_GIANT_IMAGES[giant.id];
        const isPressed = pressedId === giant.id;
        const isColored = isMapSectionColored(playerEconomy, giant.id);
        const isInteractive = onGiantClick != null;

        return (
          <div
            key={giant.id}
            className={[
              'map-giants__giant',
              isInteractive ? 'map-giants__giant--interactive' : null,
              isPressed ? 'map-giants__giant--pressed' : null,
              isColored ? null : 'map-giants__giant--grayscale',
            ]
              .filter(Boolean)
              .join(' ')}
            style={{
              left: giant.left,
              top: giant.top,
              width: giant.width,
              height: giant.height,
            }}
            onClick={
              isInteractive
                ? () => {
                    setPressedId(null);
                    requestAnimationFrame(() => setPressedId(giant.id));
                    onGiantClick(giant.id);
                  }
                : undefined
            }
            onAnimationEnd={
              isInteractive
                ? (event) => {
                    if (event.target !== event.currentTarget) return;
                    setPressedId((id) => (id === giant.id ? null : id));
                  }
                : undefined
            }
          >
            <img
              className="map-giants__img"
              src={imageSrc}
              alt=""
              draggable={false}
              style={{
                left: giant.idle.left - giant.left,
                top: giant.idle.top - giant.top,
                width: giant.idle.width,
                height: giant.idle.height,
              }}
            />
          </div>
        );
      })}
    </div>
  );
}
