import { Fragment } from 'react';
import type { BoosterKind } from '../../../../domain/catalog/boosters';
import { RUNNER_LANE_MAX } from '../../../../domain/runner/runnerConstants';
import type {
  RunnerBoosterPickup,
  RunnerDecorSprite,
  RunnerLevel,
  RunnerObstacle,
  RunnerSpark,
} from '../../../../domain/runner/runnerTypes';
import type { LevelCanvasLayout } from './layout/runnerLevelLayout';
import { projectSvgPointInWorld } from './layout/runnerLevelLayout';
import {
  LEVEL_COLLECTIBLE_ICON_URL,
  LEVEL_ITEM_SHINE_URL,
  LEVEL_SHIELD_BOOSTER_ICON_URL,
  LEVEL_SPEED_BOOSTER_ICON_URL,
  getDecorSpriteUrl,
  getObstacleSpriteUrl,
  getStaticObstacleUrl,
} from './levelVisualAssets';
import { LEVEL_GAMEPLAY_Z_INDEX } from './gameplayConstants';
import './LevelWorldSprites.css';

type WorldSpriteProps = {
  svgX: number;
  svgY: number;
  layout: LevelCanvasLayout;
  widthPx: number;
  heightPx: number;
  src: string;
  zIndex: number;
  opacity?: number;
  /** Точка спрайта (0..1), которая ставится в (svgX, svgY); по умолчанию центр. */
  anchor?: { x: number; y: number };
  /** Если задано — спрайт непрерывно вращается на 360°, период оборота в секундах. */
  spinDurationSec?: number;
  /** Если задано — спрайт плавно покачивается вверх-вниз, период в секундах. */
  wobbleDurationSec?: number;
};

function WorldSprite({
  svgX,
  svgY,
  layout,
  widthPx,
  heightPx,
  src,
  zIndex,
  opacity = 1,
  anchor,
  spinDurationSec,
  wobbleDurationSec,
}: WorldSpriteProps) {
  const { leftPx, topPx } = projectSvgPointInWorld(svgX, svgY, layout);
  const anchorXPct = (anchor?.x ?? 0.5) * 100;
  const anchorYPct = (anchor?.y ?? 0.5) * 100;
  const positionStyle = {
    position: 'absolute' as const,
    left: leftPx,
    top: topPx,
    width: widthPx,
    height: heightPx,
    transform: `translate(-${anchorXPct}%, -${anchorYPct}%)`,
    zIndex,
    opacity,
    pointerEvents: 'none' as const,
  };
  if (spinDurationSec == null && wobbleDurationSec == null) {
    return <img src={src} alt="" draggable={false} style={positionStyle} />;
  }
  const animationClassName =
    spinDurationSec != null ? 'level-world-sprite__spin' : 'level-world-sprite__wobble';
  const animationDurationSec = spinDurationSec ?? wobbleDurationSec;
  return (
    <div style={positionStyle}>
      <img
        src={src}
        alt=""
        draggable={false}
        className={animationClassName}
        style={{
          width: '100%',
          height: '100%',
          display: 'block',
          animationDuration: `${animationDurationSec}s`,
        }}
      />
    </div>
  );
}

function laneToSvgY(lane: number, viewBoxHeight: number): number {
  return (RUNNER_LANE_MAX - lane) * viewBoxHeight;
}

function spriteSizePx(hitboxWidthS: number, hitboxHeightLane: number, level: RunnerLevel, layout: LevelCanvasLayout) {
  return {
    widthPx: hitboxWidthS * layout.displayScale,
    heightPx: hitboxHeightLane * level.viewBox.height * layout.displayScale,
  };
}

function renderDecor(decor: RunnerDecorSprite, level: RunnerLevel, layout: LevelCanvasLayout) {
  const opacity = decor.opacity ?? 1;
  if (opacity <= 0) {
    return null;
  }
  const { widthPx, heightPx } = spriteSizePx(
    decor.widthS,
    decor.heightLane,
    level,
    layout,
  );
  const svgX = level.startPointSvgX + decor.centerS;
  const svgY = laneToSvgY(decor.centerLane, level.viewBox.height);
  const zIndex =
    decor.layer === 'front'
      ? LEVEL_GAMEPLAY_Z_INDEX.FX_FRONT
      : LEVEL_GAMEPLAY_Z_INDEX.DECORS;
  return (
    <WorldSprite
      key={decor.id}
      svgX={svgX}
      svgY={svgY}
      layout={layout}
      widthPx={widthPx}
      heightPx={heightPx}
      src={getDecorSpriteUrl(decor.spriteKey)}
      zIndex={zIndex}
      opacity={opacity}
      anchor={decor.anchor}
      spinDurationSec={decor.spinDurationSec}
      wobbleDurationSec={decor.wobbleDurationSec}
    />
  );
}

function renderObstacle(
  obstacle: RunnerObstacle,
  level: RunnerLevel,
  layout: LevelCanvasLayout,
) {
  const widthS = obstacle.visualWidthS ?? obstacle.hitbox.widthS;
  const heightLane = obstacle.visualHeightLane ?? obstacle.hitbox.heightLane;
  const centerS = obstacle.visualCenterS ?? obstacle.hitbox.centerS;
  const centerLane = obstacle.visualCenterLane ?? obstacle.hitbox.centerLane;
  const { widthPx, heightPx } = spriteSizePx(widthS, heightLane, level, layout);
  const svgX = level.startPointSvgX + centerS;
  const svgY = laneToSvgY(centerLane, level.viewBox.height);
  const src =
    obstacle.spriteKey != null
      ? getObstacleSpriteUrl(obstacle.spriteKey)
      : getStaticObstacleUrl(level.giantId);
  const zIndex =
    obstacle.layer === 'front'
      ? LEVEL_GAMEPLAY_Z_INDEX.OBSTACLES_FRONT
      : LEVEL_GAMEPLAY_Z_INDEX.OBSTACLES;
  return (
    <WorldSprite
      key={obstacle.id}
      svgX={svgX}
      svgY={svgY}
      layout={layout}
      widthPx={widthPx}
      heightPx={heightPx}
      src={src}
      zIndex={zIndex}
      opacity={obstacle.opacity ?? 1}
      wobbleDurationSec={obstacle.wobbleDurationSec}
      spinDurationSec={obstacle.spinDurationSec}
    />
  );
}

function renderSpark(spark: RunnerSpark, level: RunnerLevel, layout: LevelCanvasLayout) {
  const { widthPx, heightPx } = spriteSizePx(
    spark.hitbox.widthS,
    spark.hitbox.heightLane,
    level,
    layout,
  );
  const svgX = level.startPointSvgX + spark.hitbox.centerS;
  const svgY = laneToSvgY(spark.hitbox.centerLane, level.viewBox.height);
  return (
    <WorldSprite
      key={spark.id}
      svgX={svgX}
      svgY={svgY}
      layout={layout}
      widthPx={widthPx}
      heightPx={heightPx}
      src={LEVEL_COLLECTIBLE_ICON_URL}
      zIndex={LEVEL_GAMEPLAY_Z_INDEX.SPARKS}
    />
  );
}

function boosterIcon(kind: BoosterKind): string {
  if (kind === 'shield') {
    return LEVEL_SHIELD_BOOSTER_ICON_URL;
  }
  if (kind === 'speed') {
    return LEVEL_SPEED_BOOSTER_ICON_URL;
  }
  return LEVEL_SHIELD_BOOSTER_ICON_URL;
}

/** Shine sits behind the booster icon, sized off the icon's larger side. */
const BOOSTER_SHINE_SCALE = 1.8;

function renderBooster(booster: RunnerBoosterPickup, level: RunnerLevel, layout: LevelCanvasLayout) {
  const { widthPx, heightPx } = spriteSizePx(
    booster.hitbox.widthS,
    booster.hitbox.heightLane,
    level,
    layout,
  );
  const svgX = level.startPointSvgX + booster.hitbox.centerS;
  const svgY = laneToSvgY(booster.hitbox.centerLane, level.viewBox.height);
  const shineSizePx = Math.max(widthPx, heightPx) * BOOSTER_SHINE_SCALE;
  return (
    <Fragment key={booster.id}>
      <WorldSprite
        svgX={svgX}
        svgY={svgY}
        layout={layout}
        widthPx={shineSizePx}
        heightPx={shineSizePx}
        src={LEVEL_ITEM_SHINE_URL}
        zIndex={LEVEL_GAMEPLAY_Z_INDEX.BOOSTERS}
      />
      <WorldSprite
        svgX={svgX}
        svgY={svgY}
        layout={layout}
        widthPx={widthPx}
        heightPx={heightPx}
        src={boosterIcon(booster.kind)}
        zIndex={LEVEL_GAMEPLAY_Z_INDEX.BOOSTERS}
      />
    </Fragment>
  );
}

type LevelWorldSpritesProps = {
  level: RunnerLevel;
  layout: LevelCanvasLayout;
};

export function LevelWorldSprites({ level, layout }: LevelWorldSpritesProps) {
  return (
    <>
      {level.decors.map((decor) => renderDecor(decor, level, layout))}
      {level.sparks
        .filter((s) => !s.consumed)
        .map((spark) => renderSpark(spark, level, layout))}
      {level.boosters
        .filter((b) => !b.consumed)
        .map((booster) => renderBooster(booster, level, layout))}
      {level.obstacles
        .filter((o) => !o.consumed && (o.opacity ?? 1) > 0)
        .map((obstacle) => renderObstacle(obstacle, level, layout))}
    </>
  );
}
