import type { RunnerDecorSprite, RunnerLevel } from './runnerTypes';

/** Top-left placement from layout (SVG user units). */
const GLASSES_SVG = {
  id: 'willy_m',
  x: 5510.4121,
  y: -120,
  width: 2818,
  height: 930,
} as const;

function svgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

/** Статичные очки Willy: без коллизии, слой поверх игрока. */
export function buildWillyGlassesDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'willy') {
    return [];
  }
  const cx = GLASSES_SVG.x + GLASSES_SVG.width / 2;
  const cy = GLASSES_SVG.y + GLASSES_SVG.height / 2;
  return [
    {
      id: GLASSES_SVG.id,
      spriteKey: 'willy_m',
      centerS: cx - level.startPointSvgX,
      centerLane: svgYToLane(cy, level.viewBox.height),
      widthS: GLASSES_SVG.width,
      heightLane: GLASSES_SVG.height / level.viewBox.height,
      layer: 'front',
    },
  ];
}
