import type { Dispatch, SetStateAction } from 'react';
import type { ArrowDirection } from '../components/atomic/buttons/arrows/Arrows';
import type { NavBarTab } from '../components/composite/nav/nav_bar/NavBar';
import { VIEWPORT_HEIGHT, VIEWPORT_WIDTH } from '../../../domain/Constants';
import type { GiantId } from './giants/giantPositions';
import {
  MAP_HEIGHT,
  MAP_PAN_STEP,
  MAP_SCALE,
  MAP_WIDTH,
} from './lands/landPositions';

export type MapScreenProps = {
  activeTab?: NavBarTab;
  /** Pass balance for HUD ticket button. */
  passesBalance?: number;
  /** Current courier license tier name for HUD button. */
  playerLevelName?: string;
  /** Average delivery rating for HUD star button. */
  averageRating?: number;
  /** Last rating delta after a completed delivery (HUD coeff). */
  lastRatingDelta?: number | null;
  onTabChange?: (tab: NavBarTab) => void;
  onTakeDelivery?: (giantId: GiantId, orderIndex: number) => void;
  onOpenTickets?: () => void;
  onOpenRating?: () => void;
  onOpenPlayerLevel?: () => void;
};

export type MapCamera = {
  x: number;
  y: number;
  /** World display scale; base is MAP_SCALE, max is MAP_ZOOM_MAX_SCALE. */
  scale: number;
};

export type MapScreenState = {
  camera: MapCamera;
  setCamera: Dispatch<SetStateAction<MapCamera>>;
};

export type MapScreenModel = {
  camera: MapCamera;
  setCamera: Dispatch<SetStateAction<MapCamera>>;
  canNavigate: Record<ArrowDirection, boolean>;
  activeTab: NavBarTab;
  onTabChange?: (tab: NavBarTab) => void;
  onTakeDelivery?: (giantId: GiantId, orderIndex: number) => void;
  onOpenTickets?: () => void;
  onOpenRating?: () => void;
  onOpenPlayerLevel?: () => void;
  passesBalance?: number;
  playerLevelName?: string;
  averageRating?: number;
  lastRatingDelta?: number | null;
};

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

/** Interactive zoom: base fit scale … +44% (~20% above previous +20% cap). */
export const MAP_ZOOM_MIN_SCALE = MAP_SCALE;
export const MAP_ZOOM_MAX_SCALE = MAP_SCALE * 1.44;

export function maxCameraForScale(scale: number): { x: number; y: number } {
  return {
    x: Math.max(0, MAP_WIDTH * scale - VIEWPORT_WIDTH),
    y: Math.max(0, MAP_HEIGHT * scale - VIEWPORT_HEIGHT),
  };
}

export const MAX_CAMERA_X = maxCameraForScale(MAP_SCALE).x;
export const MAX_CAMERA_Y = maxCameraForScale(MAP_SCALE).y;

export const INITIAL_CAMERA: MapCamera = {
  x: MAX_CAMERA_X / 2,
  y: MAX_CAMERA_Y / 2,
  scale: MAP_SCALE,
};

export const MAP_SCREEN_WORLD = {
  width: MAP_WIDTH,
  height: MAP_HEIGHT,
  scale: MAP_SCALE,
  panStep: MAP_PAN_STEP,
};

export function clampCamera(camera: MapCamera): MapCamera {
  const scale = clamp(
    Number.isFinite(camera.scale) ? camera.scale : MAP_SCALE,
    MAP_ZOOM_MIN_SCALE,
    MAP_ZOOM_MAX_SCALE,
  );
  const max = maxCameraForScale(scale);
  return {
    x: clamp(camera.x, 0, max.x),
    y: clamp(camera.y, 0, max.y),
    scale,
  };
}

export function createMapScreenModel(
  props: MapScreenProps,
  state: MapScreenState,
): MapScreenModel {
  const { camera, setCamera } = state;
  const max = maxCameraForScale(camera.scale);

  return {
    camera,
    setCamera,
    canNavigate: {
      left: camera.x > 0,
      right: camera.x < max.x,
      up: camera.y > 0,
      down: camera.y < max.y,
    },
    activeTab: props.activeTab ?? 'map',
    onTabChange: props.onTabChange,
    onTakeDelivery: props.onTakeDelivery,
    onOpenTickets: props.onOpenTickets,
    onOpenRating: props.onOpenRating,
    onOpenPlayerLevel: props.onOpenPlayerLevel,
    passesBalance: props.passesBalance,
    playerLevelName: props.playerLevelName,
    averageRating: props.averageRating,
    lastRatingDelta: props.lastRatingDelta,
  };
}
