import '../components/atomic/layout/app_screen/app_screen.css';
import { GoHomeButton } from '../components/atomic/buttons/go_home_button/GoHomeButton';
import { RestartButton } from '../components/atomic/buttons/restart_button/RestartButton';
import { ScreenHeader } from '../components/atomic/layout/screen_header/ScreenHeader';
import { SkyAtmosphere } from '../components/composite/atmosphere/sky_atmosphere/SkyAtmosphere';
import type { ScreenViewProps } from '../shared/screenViewProps';
import { HeaderText } from './header_text/HeaderText';
import { ResultStatsContent } from './result_stats_content/ResultStatsContent';
import type { DeliveryResultScreenController } from './DeliveryResultScreenController';
import type { DeliveryResultScreenModel } from './DeliveryResultScreenModelScreen';
import './delivery_result_screen.css';

export type DeliveryResultScreenViewProps = ScreenViewProps<
  DeliveryResultScreenModel,
  DeliveryResultScreenController
>;

/** Delivery result screen. */
export function DeliveryResultScreenView({
  model,
  controller,
}: DeliveryResultScreenViewProps) {
  return (
    <div className="app-screen delivery-result-screen">
      <SkyAtmosphere
        variant="delivery"
        sunBeamsClassName="delivery-result-screen__sun-beams"
      />
      <ScreenHeader showSubHeader={false} />
      <HeaderText />
      <ResultStatsContent rating={model.rating} />
      <RestartButton
        onClick={controller.handleRestart}
        disabled={!model.canRestart}
      />
      <GoHomeButton onClick={controller.handleGoHome} />
    </div>
  );
}
