import type { RunnerDecorSprite, RunnerLevel, RunnerSerjDecorSpriteKey } from './runnerTypes';

type SerjDecorDef = {
  id: string;
  spriteKey: RunnerSerjDecorSpriteKey;
  /** Центр bbox path в serj/modificators.svg (`<g id="1">`..`<g id="4">`, без blur-паддинга фильтра). */
  centerSvgX: number;
  centerSvgY: number;
  widthSvg: number;
  heightSvg: number;
  /** Период покачивания вверх-вниз, сек. */
  wobbleDurationSec: number;
};

/** Позиции из serj/modificators.svg: центры bbox групп `1`..`4`. Без хитбокса — игрок проходит сквозь. */
export const SERJ_DECOR_DEFS: readonly SerjDecorDef[] = [
  { id: 'serj_1', spriteKey: 'serj_1', centerSvgX: 7294.12, centerSvgY: 889.34, widthSvg: 2057.95, heightSvg: 937.32, wobbleDurationSec: 2.6 },
  { id: 'serj_2', spriteKey: 'serj_2', centerSvgX: 7698.05, centerSvgY: 182.92, widthSvg: 599.28, heightSvg: 415.49, wobbleDurationSec: 2.2 },
  { id: 'serj_3', spriteKey: 'serj_3', centerSvgX: 5919.11, centerSvgY: 744.68, widthSvg: 599.28, heightSvg: 415.49, wobbleDurationSec: 2.8 },
  { id: 'serj_4', spriteKey: 'serj_4', centerSvgX: 6364.84, centerSvgY: 71.12, widthSvg: 2057.95, heightSvg: 937.32, wobbleDurationSec: 2.4 },
] as const;

/** Прямоугольник `#foam` из serj/modificators.svg (raw rect, без учёта blur-фильтра). */
const SERJ_FOAM_SVG = {
  id: 'serj_foam',
  x: 5659.29,
  y: -252.422,
  width: 2348.72,
  height: 1366.33,
} as const;

function serjSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function serjSvgYToLane(svgY: number, viewBoxHeight: number): number {
  return 1 - svgY / viewBoxHeight;
}

/** Новые препятствия serj: неколлизионный декор (игрок проходит сквозь), поверх игрока, с покачиванием. */
export function buildSerjObstacleDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'serj') {
    return [];
  }
  return SERJ_DECOR_DEFS.map((def) => ({
    id: def.id,
    spriteKey: def.spriteKey,
    centerS: serjSvgXToS(def.centerSvgX, level.startPointSvgX),
    centerLane: serjSvgYToLane(def.centerSvgY, level.viewBox.height),
    widthS: def.widthSvg,
    heightLane: def.heightSvg / level.viewBox.height,
    layer: 'front',
    wobbleDurationSec: def.wobbleDurationSec,
  }));
}

/** Foam serj: статичный неколлизионный декор поверх игрока. */
export function buildSerjFoamDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'serj') {
    return [];
  }
  const cx = SERJ_FOAM_SVG.x + SERJ_FOAM_SVG.width / 2;
  const cy = SERJ_FOAM_SVG.y + SERJ_FOAM_SVG.height / 2;
  return [
    {
      id: SERJ_FOAM_SVG.id,
      spriteKey: 'serj_foam',
      centerS: serjSvgXToS(cx, level.startPointSvgX),
      centerLane: serjSvgYToLane(cy, level.viewBox.height),
      widthS: SERJ_FOAM_SVG.width,
      heightLane: SERJ_FOAM_SVG.height / level.viewBox.height,
      layer: 'front',
    },
  ];
}
