import { useRef } from 'react';
import '../components/atomic/layout/app_screen/app_screen.css';
import './map_screen.css';
import {
  formatSignedRatingDelta,
  roundRating,
  shouldShowDailyPackCompleteModal,
} from '../../../domain';
import { isAdminClient } from '../../../infrastructure';
import { useAppStore } from '../../store/appStore';
import { Arrows } from '../components/atomic/buttons/arrows/Arrows';
import { TicketsScreenButton } from './tickets_screen_button/TicketsScreenButton';
import { RatingScreenButton } from './rating_screen_button/RatingScreenButton';
import { PlayerLevelScreenButton } from './player_level_screen_button/PlayerLevelScreenButton';
import { NavBar } from '../components/composite/nav/nav_bar/NavBar';
import { Lands } from './lands/Lands';
import { Giants } from './giants/Giants';
import { MapDeliveryPopups } from './delivery_popups/MapDeliveryPopups';
import { MapDeliveryHints } from './delivery_hint_icon/MapDeliveryHints';
import { AllDeliveryCompletedModal } from './all_delivery_completed/AllDeliveryCompletedModal';
import {
  MAP_SCREEN_WORLD,
  MAP_ZOOM_MAX_SCALE,
  MAP_ZOOM_MIN_SCALE,
  type MapScreenModel,
} from './MapScreenModelScreen';
import type { MapScreenController } from './MapScreenController';
import type { ScreenViewProps } from '../shared/screenViewProps';
import { useMapPan } from '../shared/gestures/useMapPan';

export type MapScreenViewProps = ScreenViewProps<
  MapScreenModel,
  MapScreenController
>;

function formatHudRating(averageRating: number | undefined): string | undefined {
  if (averageRating == null || !Number.isFinite(averageRating)) {
    return undefined;
  }
  return roundRating(averageRating).toFixed(1).replace('.', ',');
}

function formatHudRatingDelta(delta: number | null | undefined): string {
  if (delta == null || !Number.isFinite(delta)) {
    return '';
  }
  return formatSignedRatingDelta(delta).replace('.', ',');
}

export function MapScreenView({ model, controller }: MapScreenViewProps) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const showCompleteModal = useAppStore((s) =>
    shouldShowDailyPackCompleteModal(s.playerEconomy),
  );
  const resetPlayerProgressForAdmin = useAppStore((s) => s.resetPlayerProgressForAdmin);
  const pan = useMapPan({
    getCamera: () => model.camera,
    onPan: controller.handlePan,
    enabled: !showCompleteModal,
    minScale: MAP_ZOOM_MIN_SCALE,
    maxScale: MAP_ZOOM_MAX_SCALE,
    viewportRef,
  });

  const handleAdminReset = () => {
    if (!window.confirm('Сбросить прогресс доставок?')) {
      return;
    }
    void resetPlayerProgressForAdmin();
  };

  return (
    <div className="app-screen map-screen">
      <div
        ref={viewportRef}
        className="map-screen__viewport"
        style={pan.style}
        onPointerDown={pan.onPointerDown}
        onPointerMove={pan.onPointerMove}
        onPointerUp={pan.onPointerUp}
        onPointerCancel={pan.onPointerCancel}
      >
        <div
          className={[
            'map-screen__world',
            pan.isDragging ? 'map-screen__world--dragging' : '',
          ]
            .filter(Boolean)
            .join(' ')}
          style={{
            width: MAP_SCREEN_WORLD.width,
            height: MAP_SCREEN_WORLD.height,
            transform: `translate(${-model.camera.x}px, ${-model.camera.y}px) scale(${model.camera.scale})`,
            pointerEvents: showCompleteModal ? 'none' : undefined,
          }}
        >
          <Lands />
          <Giants />
          <MapDeliveryPopups onTakeDelivery={controller.handleTakeDelivery} />
        </div>
      </div>

      <Arrows
        directions={['left', 'right']}
        onNavigate={controller.handleNavigate}
        canNavigate={
          showCompleteModal
            ? { left: false, right: false }
            : model.canNavigate
        }
      />
      {showCompleteModal ? null : (
        <MapDeliveryHints camera={model.camera} directions={['left', 'right']} />
      )}
      <TicketsScreenButton
        onClick={controller.handleOpenTickets}
        count={model.passesBalance}
      />
      <PlayerLevelScreenButton
        onClick={controller.handleOpenPlayerLevel}
        name={model.playerLevelName}
      />
      <RatingScreenButton
        onClick={controller.handleOpenRating}
        rating={formatHudRating(model.averageRating)}
        changeCoeff={formatHudRatingDelta(model.lastRatingDelta)}
      />
      <NavBar
        activeTab={model.activeTab}
        onTabChange={controller.handleTabChange}
      />
      {showCompleteModal ? <AllDeliveryCompletedModal /> : null}
      {isAdminClient() ? (
        <button
          type="button"
          className="map-screen__admin-reset"
          onClick={handleAdminReset}
        >
          Сброс
        </button>
      ) : null}
    </div>
  );
}
