import type { PointerEvent as ReactPointerEvent } from 'react';
import type { CharacterId } from '../../../../domain/ids/ids';
import type { GiantId } from '../../../../domain/ids/ids';
import type { RunnerLevel, RunnerPlayer } from '../../../../domain/runner/runnerTypes';
import { VIEWPORT_WIDTH } from '../../../../domain/Constants';
import { LEVEL_GAMEPLAY_Z_INDEX } from './gameplayConstants';
import { LEVEL_PLAYFIELD_HEIGHT_PX } from './gameplayConstants';
import {
  computeRunnerFallbackLayout,
  computeRunnerLevelLayout,
  createPlayfieldConfig,
  type LevelCanvasLayout,
} from './layout/runnerLevelLayout';
import { getLevelVisualAssets } from './levelVisualAssets';
import { LevelWorldSprites } from './LevelWorldSprites';
import { LevelPlayerSprite } from './LevelPlayerSprite';
import './LevelPlayfield.css';

type PlayfieldPointerHandlers = {
  onPointerDown?: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerMove?: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerUp?: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerCancel?: (event: ReactPointerEvent<HTMLDivElement>) => void;
};

type LevelPlayfieldProps = {
  giantId: GiantId;
  level: RunnerLevel;
  player: RunnerPlayer;
  /** Наклон спрайта: -1..1 (доля от максимального угла). */
  tilt: number;
  characterId: CharacterId;
  /** Presentation-only сдвиг камеры вперёд по route s (скрывает левый край на старте). */
  cameraLeadS?: number;
  pointerHandlers?: PlayfieldPointerHandlers;
};

function LevelPlayfieldLayers({
  layout,
  level,
  player,
  tilt,
  characterId,
  giantId,
}: {
  layout: LevelCanvasLayout;
  level: RunnerLevel;
  player: RunnerPlayer;
  tilt: number;
  characterId: CharacterId;
  giantId: GiantId;
}) {
  const assets = getLevelVisualAssets(giantId);
  return (
    <div
      className="level-playfield__world"
      style={{
        left: layout.canvasLeftPx + layout.contentOffsetPx,
        top: layout.canvasTopPx,
        width: layout.canvasWidthPx,
        height: layout.canvasHeightPx,
      }}
    >
      <img
        className="level-playfield__bg"
        src={assets.backgroundUrl}
        alt=""
        draggable={false}
        style={{ zIndex: LEVEL_GAMEPLAY_Z_INDEX.BACKGROUND }}
      />
      <LevelWorldSprites level={level} layout={layout} />
      <LevelPlayerSprite
        level={level}
        player={player}
        layout={layout}
        tilt={tilt}
        characterId={characterId}
      />
      {assets.foregroundUrl != null ? (
        <img
          className="level-playfield__fg"
          src={assets.foregroundUrl}
          alt=""
          draggable={false}
          style={{ zIndex: LEVEL_GAMEPLAY_Z_INDEX.FOREGROUND }}
        />
      ) : null}
    </div>
  );
}

export function LevelPlayfield({
  giantId,
  level,
  player,
  tilt,
  characterId,
  cameraLeadS = 0,
  pointerHandlers,
}: LevelPlayfieldProps) {
  const playfield = createPlayfieldConfig(VIEWPORT_WIDTH, LEVEL_PLAYFIELD_HEIGHT_PX);
  const layout =
    player != null
      ? computeRunnerLevelLayout(level, playfield, player, cameraLeadS)
      : computeRunnerFallbackLayout(level, playfield);

  return (
    <div className="level-playfield" {...pointerHandlers}>
      <LevelPlayfieldLayers
        layout={layout}
        level={level}
        player={player}
        tilt={tilt}
        characterId={characterId}
        giantId={giantId}
      />
    </div>
  );
}
