import headerBackgroundImg from '../content/header/header_background.png';
import headerTextImg from '../content/header/header_text.png';
import './FailDeliveryHeader.css';

/** From Figma title_bad (142:17540) + «ДостаВКа Провалена» (142:17542). */
export function FailDeliveryHeader() {
  return (
    <div className="fail-delivery-header">
      <img
        className="fail-delivery-header__background"
        src={headerBackgroundImg}
        alt=""
        draggable={false}
        aria-hidden
      />
      <img
        className="fail-delivery-header__text"
        src={headerTextImg}
        alt="Доставка провалена"
        draggable={false}
      />
    </div>
  );
}
