import { useEffect, useRef, type Dispatch, type SetStateAction } from 'react';
import {
  handleRunnerBoosterCollisions,
  handleRunnerModifierZoneEnter,
  handleRunnerObstacleCollisions,
  handleRunnerSparkCollisions,
} from '../../../../../application/runner/runnerCollisionUseCases';
import type { RunnerLevel, RunnerPlayer } from '../../../../../domain/runner/runnerTypes';
import {
  playRunnerBooster,
  playRunnerHit,
  playRunnerSpark,
} from '../../../../assets/preloadSounds';

export function useRunnerCollisions(
  level: RunnerLevel | null,
  player: RunnerPlayer | null,
  setLevel: Dispatch<SetStateAction<RunnerLevel | null>>,
  setPlayer: Dispatch<SetStateAction<RunnerPlayer | null>>,
  onSparksCollected: (count: number) => void,
  onSpeedBoostersCollected: (count: number) => void,
): void {
  const obstacleActiveRef = useRef<Set<string>>(new Set());
  const sparkActiveRef = useRef<Set<string>>(new Set());
  const boosterActiveRef = useRef<Set<string>>(new Set());

  useEffect(() => {
    obstacleActiveRef.current = new Set();
    sparkActiveRef.current = new Set();
    boosterActiveRef.current = new Set();
  }, [level?.giantId]);

  useEffect(() => {
    if (level == null || player == null) {
      return;
    }

    let nextLevel = level;
    let nextPlayer = player;

    const obstacleBefore = obstacleActiveRef.current.size;
    const obstacleResult = handleRunnerObstacleCollisions(
      nextLevel,
      nextPlayer,
      obstacleActiveRef.current,
    );
    nextLevel = obstacleResult.level;
    nextPlayer = obstacleResult.player;
    obstacleActiveRef.current = obstacleResult.nextActiveCollisionIds;
    if (obstacleResult.nextActiveCollisionIds.size > obstacleBefore) {
      playRunnerHit();
    }

    const sparkResult = handleRunnerSparkCollisions(
      nextLevel,
      nextPlayer,
      sparkActiveRef.current,
    );
    nextLevel = sparkResult.level;
    sparkActiveRef.current = sparkResult.nextActiveCollisionIds;
    if (sparkResult.sparksCollected > 0) {
      playRunnerSpark();
      onSparksCollected(sparkResult.sparksCollected);
    }

    const boosterBefore = boosterActiveRef.current.size;
    const boosterResult = handleRunnerBoosterCollisions(
      nextLevel,
      nextPlayer,
      boosterActiveRef.current,
    );
    nextLevel = boosterResult.level;
    nextPlayer = boosterResult.player;
    boosterActiveRef.current = boosterResult.nextActiveCollisionIds;
    if (boosterResult.nextActiveCollisionIds.size > boosterBefore) {
      playRunnerBooster();
    }
    if (boosterResult.speedBoostersCollected > 0) {
      onSpeedBoostersCollected(boosterResult.speedBoostersCollected);
    }

    const modifierResult = handleRunnerModifierZoneEnter(nextLevel, nextPlayer);
    nextLevel = modifierResult.level;

    if (nextLevel !== level) {
      setLevel(nextLevel);
    }
    if (nextPlayer !== player) {
      setPlayer(nextPlayer);
    }
  }, [level, player, setLevel, setPlayer, onSparksCollected, onSpeedBoostersCollected]);
}
