import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { getNextQuizQuestion, isQuizComplete, type QuizQuestion } from '../../../domain';
import {
  playDeliveryFail,
  playDeliverySuccess,
  playUiClick,
} from '../../assets/preloadSounds';
import { useAppStore } from '../../store/appStore';
import {
  createQuizScreenModel,
  type QuizAnswerFeedback,
  type QuizScreenProps,
} from './QuizScreenModelScreen';
import { QuizScreenController } from './QuizScreenController';
import { QuizScreenView } from './QuizScreenView';

export type { QuizScreenProps } from './QuizScreenModelScreen';

const ANSWER_FEEDBACK_MS = 5000;

export function QuizScreen({ onGoBack, onClueClick, ...restProps }: QuizScreenProps) {
  const playerEconomy = useAppStore((state) => state.playerEconomy);
  const economyQuestion = useMemo(
    () => getNextQuizQuestion(playerEconomy),
    [playerEconomy],
  );

  const [activeQuestion, setActiveQuestion] = useState<QuizQuestion | null>(economyQuestion);
  const [feedback, setFeedback] = useState<QuizAnswerFeedback | null>(null);
  const advanceTimerRef = useRef<number | null>(null);

  useEffect(() => {
    if (feedback != null) {
      return;
    }
    setActiveQuestion(economyQuestion);
  }, [economyQuestion, feedback]);

  useEffect(
    () => () => {
      if (advanceTimerRef.current != null) {
        window.clearTimeout(advanceTimerRef.current);
      }
    },
    [],
  );

  const handleAnswer = useCallback(
    (index: number) => {
      if (feedback != null || activeQuestion == null) {
        return;
      }

      const question = activeQuestion;
      const correct = index === question.correctIndex;

      playUiClick();
      if (correct) {
        playDeliverySuccess();
      } else {
        playDeliveryFail();
      }

      // Lock the current question before the store updates economy/next question,
      // otherwise the sync effect advances activeQuestion before feedback is set.
      setFeedback({
        selectedIndex: index,
        correctIndex: question.correctIndex,
        correct,
      });

      if (advanceTimerRef.current != null) {
        window.clearTimeout(advanceTimerRef.current);
      }

      void useAppStore
        .getState()
        .submitQuizAnswer(question.id, index)
        .then((result) => {
          setFeedback({
            selectedIndex: index,
            correctIndex: question.correctIndex,
            correct: result.correct,
          });

          advanceTimerRef.current = window.setTimeout(() => {
            advanceTimerRef.current = null;
            setFeedback(null);
            const economy = useAppStore.getState().playerEconomy;
            if (getNextQuizQuestion(economy) == null || isQuizComplete(economy)) {
              onGoBack?.();
            }
          }, ANSWER_FEEDBACK_MS);
        })
        .catch(() => {
          setFeedback(null);
        });
    },
    [activeQuestion, feedback, onGoBack],
  );

  const model = createQuizScreenModel({
    ...restProps,
    onGoBack,
    onClueClick,
    question: activeQuestion,
    feedback,
    onAnswer: handleAnswer,
  });
  const controller = new QuizScreenController(model);

  return <QuizScreenView model={model} controller={controller} />;
}
