import type {
  RunnerDecorSprite,
  RunnerFactorDecorSpriteKey,
  RunnerLevel,
} from './runnerTypes';

/** Высота полосы геймплея в Faktor Plant.svg (viewBox ≈ play strip). */
export const FACTOR_PLAY_STRIP_HEIGHT = 929.588;

/** Длительность одной ноги A→B / B→A, сек. */
export const FACTOR_MIRAGE_FLIGHT_DURATION_SEC = 2.5;

/** Пауза на конечных точках (opacity 0), сек. */
export const FACTOR_MIRAGE_DWELL_SEC = 0.5;

/** Сдвиг старта между объектами, сек. */
export const FACTOR_MIRAGE_STAGGER_SEC = 0.25;

/** Период оборота static.png (пила), сек. Слегка разный у соседних, чтобы не синхронизировались. */
const FACTOR_STATIC_SPIN_DURATIONS_SEC = [3.2, 3.6, 4.0, 4.4] as const;

export function factorStaticSpinDurationSec(index: number): number {
  return FACTOR_STATIC_SPIN_DURATIONS_SEC[index % FACTOR_STATIC_SPIN_DURATIONS_SEC.length];
}

type FactorMiragePathDef = {
  id: string;
  spriteKey: RunnerFactorDecorSpriteKey;
  layer: 'behind' | 'front';
  /** Центр bbox в modificators-a (старт). */
  startSvgX: number;
  startSvgY: number;
  /** Центр bbox в modificators-b (финиш). */
  finishSvgX: number;
  finishSvgY: number;
  widthSvg: number;
  heightSvg: number;
};

/**
 * Пути из Faktor Plant.svg: центр bbox группы (старт) → сдвиг по X (финиш).
 * Второго кадра (modificators-b) в новом арте нет, поэтому финиш получен
 * тем же сдвигом, что был у старых деталей и foam (Δx ≈ −530 / −156).
 */
export const FACTOR_MIRAGE_PATHS: readonly FactorMiragePathDef[] = [
  {
    id: 'factor_mirage_1',
    spriteKey: 'factor_1',
    layer: 'behind',
    startSvgX: 6850.68,
    startSvgY: 875.37,
    finishSvgX: 6320.68,
    finishSvgY: 875.37,
    widthSvg: 2774,
    heightSvg: 306,
  },
  {
    id: 'factor_mirage_2',
    spriteKey: 'factor_2',
    layer: 'behind',
    startSvgX: 7041.76,
    startSvgY: 164.71,
    finishSvgX: 6511.76,
    finishSvgY: 164.71,
    widthSvg: 2384,
    heightSvg: 415,
  },
  {
    id: 'factor_mirage_foam',
    spriteKey: 'factor_foam',
    layer: 'front',
    startSvgX: 7013.41,
    startSvgY: 508.02,
    finishSvgX: 6857.33,
    finishSvgY: 508.02,
    widthSvg: 3179,
    heightSvg: 930,
  },
] as const;

export function factorSvgYToLane(svgY: number): number {
  return 1 - svgY / FACTOR_PLAY_STRIP_HEIGHT;
}

export function factorSvgXToS(svgX: number, startPointSvgX: number): number {
  return svgX - startPointSvgX;
}

function visualHeightLane(heightSvg: number): number {
  return heightSvg / FACTOR_PLAY_STRIP_HEIGHT;
}

export function buildFactorMirageDecors(level: RunnerLevel): RunnerDecorSprite[] {
  const { startPointSvgX } = level;
  return FACTOR_MIRAGE_PATHS.map((path, index) => {
    const startS = factorSvgXToS(path.startSvgX, startPointSvgX);
    const startLane = factorSvgYToLane(path.startSvgY);
    const finishS = factorSvgXToS(path.finishSvgX, startPointSvgX);
    const finishLane = factorSvgYToLane(path.finishSvgY);
    return {
      id: path.id,
      spriteKey: path.spriteKey,
      centerS: startS,
      centerLane: startLane,
      widthS: path.widthSvg,
      heightLane: visualHeightLane(path.heightSvg),
      opacity: 0,
      layer: path.layer,
      motion: {
        kind: 'pathPingPong',
        startS,
        startLane,
        finishS,
        finishLane,
        durationSec: FACTOR_MIRAGE_FLIGHT_DURATION_SEC,
        dwellSec: FACTOR_MIRAGE_DWELL_SEC,
        elapsedSec: -index * FACTOR_MIRAGE_STAGGER_SEC,
        phase: 'toFinish',
      },
    };
  });
}

export function hasActiveFactorMirageDecors(level: RunnerLevel): boolean {
  const ids = new Set(FACTOR_MIRAGE_PATHS.map((p) => p.id));
  return level.decors.some((d) => ids.has(d.id) && d.motion?.kind === 'pathPingPong');
}
