/** Whether the task at list index is done and should be inactive. */
export function isTaskListItemCompleted(
  taskIndex: number,
  playerEconomy: PlayerEconomyState,
  nowMs = Date.now(),
): boolean {
  if (taskIndex === TASK_INDEX_NOTIFICATIONS) {
    return isNotificationsRewardClaimed(playerEconomy);
  }
  if (taskIndex === TASK_INDEX_DAILY_LOGIN) {
    return (
      isDailyLoginStreakCompleted(playerEconomy) ||
      isDailyLoginRewardClaimedToday(playerEconomy, nowMs)
    );
  }
  if (taskIndex === TASK_INDEX_QUIZ) {
    return isQuizComplete(playerEconomy);
  }
  if (taskIndex === TASK_INDEX_VK_SUBSCRIBE) {
    return isVkSubscribeRewardClaimed(playerEconomy);
  }
  return false;
}

export function buildTaskCards(
  playerEconomy: PlayerEconomyState,
  nowMs = Date.now(),
): TaskCardModel[] {
  return TASK_TEMPLATES.map((template, index) => ({
    ...template,
    completed: isTaskListItemCompleted(index, playerEconomy, nowMs),
  }));
}

export type TaskListScreenModel = InfoPopupState & {
  tasks: readonly TaskCardModel[];
  onNavigate?: (direction: ArrowDirection) => void;
  onTaskClick?: (taskIndex: number) => void;
  onInfoClick?: () => void;
  onGoBack?: () => void;
};

export function createTaskListScreenModel(
  props: TaskListScreenProps,
  state: TicketsScreenState,
): TaskListScreenModel {
  return {
    tasks: buildTaskCards(props.playerEconomy),
    infoOpen: state.infoOpen,
    setInfoOpen: state.setInfoOpen,
    onInfoClick: props.onInfoClick,
    onNavigate: props.onNavigate,
    onTaskClick: props.onTaskClick,
    onGoBack: props.onGoBack,
  };
}
