import type { BoosterKind } from '../catalog/boosters';
import type { RunnerPlayer } from './runnerTypes';

export function hasRunnerShieldBooster(player: RunnerPlayer): boolean {
  return player.activeBooster?.kind === 'shield';
}

export function hasRunnerSpeedBooster(player: RunnerPlayer): boolean {
  return player.activeBooster?.kind === 'speed';
}

export function runnerSpriteVariant(player: RunnerPlayer): BoosterKind | 'normal' {
  const kind = player.activeBooster?.kind;
  if (kind === 'shield' || kind === 'speed') {
    return kind;
  }
  return 'normal';
}

export type RunnerLevelSession = {
  level: import('./runnerTypes').RunnerLevel;
  player: RunnerPlayer;
};
