import './pause_screen.css';
import { ScreenHeader } from '../components/atomic/layout/screen_header/ScreenHeader';
import type { ScreenViewProps } from '../shared/screenViewProps';
import { BlurBackground } from './blur_background/BlurBackground';
import { ContinueButton } from './continue_button/ContinueButton';
import { GoHomeButton } from './go_home_button/GoHomeButton';
import { MuteToggleButton } from './mute_toggle/MuteToggleButton';
import { PlaqueFrame } from './plaque_frame/PlaqueFrame';
import { HeaderText } from './texts/HeaderText';
import type { PauseScreenController } from './PauseScreenController';
import type { PauseScreenModel } from './PauseScreenModelScreen';

export type PauseScreenViewProps = ScreenViewProps<
  PauseScreenModel,
  PauseScreenController
>;

/** Pause modal stub. */
export function PauseScreenView({ model, controller }: PauseScreenViewProps) {
  return (
    <>
      <BlurBackground />
      <div className="pause-screen">
        <ScreenHeader showSubHeader={false} />
        <HeaderText />
        <PlaqueFrame />
        <MuteToggleButton
          muted={model.audioMuted}
          onClick={controller.handleToggleMute}
        />
        <ContinueButton onClick={controller.handleContinue} />
        <GoHomeButton onClick={controller.handleGoHome} />
      </div>
    </>
  );
}
