import { useState } from 'react';
import { playUiClickB } from '../../../../../assets/preloadSounds';
import './NavBar.css';
import { NavBarButton } from '../../../atomic/buttons/nav_bar_button/NavBarButton';
import mapIcon from './map_icon.png';
import deliveriesIcon from './deliveries_icon.png';
import rewardsIcon from './rewards_icon.png';

export type NavBarTab = 'map' | 'deliveries' | 'rewards';

type NavBarProps = {
  activeTab?: NavBarTab;
  onTabChange?: (tab: NavBarTab) => void;
};

/**
 * Figma `game_control_panel` (59:15883) — three nav tabs at mockup positions.
 */
export function NavBar({ activeTab: controlledTab, onTabChange }: NavBarProps) {
  const [uncontrolledTab, setUncontrolledTab] = useState<NavBarTab>('map');
  const activeTab = controlledTab ?? uncontrolledTab;

  const select = (tab: NavBarTab) => {
    playUiClickB();
    if (controlledTab === undefined) {
      setUncontrolledTab(tab);
    }
    onTabChange?.(tab);
  };

  return (
    <nav className="nav-bar" aria-label="Навигация">
      <NavBarButton
        className="nav-bar__button--map"
        active={activeTab === 'map'}
        aria-label="Карта"
        onClick={() => select('map')}
      >
        <img
          className="nav-bar__icon nav-bar__icon--map"
          src={mapIcon}
          alt=""
          draggable={false}
          aria-hidden
        />
        <span className="nav-bar__label nav-bar__label--map" aria-hidden>
          Карта
        </span>
      </NavBarButton>
      <NavBarButton
        className="nav-bar__button--deliveries"
        active={activeTab === 'deliveries'}
        aria-label="Мои доставки"
        onClick={() => select('deliveries')}
      >
        <img
          className="nav-bar__icon nav-bar__icon--deliveries"
          src={deliveriesIcon}
          alt=""
          draggable={false}
          aria-hidden
        />
        <span className="nav-bar__label nav-bar__label--deliveries" aria-hidden>
          Мои доставки
        </span>
      </NavBarButton>
      <NavBarButton
        className="nav-bar__button--rewards"
        active={activeTab === 'rewards'}
        aria-label="Награды"
        onClick={() => select('rewards')}
      >
        <img
          className="nav-bar__icon nav-bar__icon--rewards"
          src={rewardsIcon}
          alt=""
          draggable={false}
          aria-hidden
        />
        <span className="nav-bar__label nav-bar__label--rewards" aria-hidden>
          Награды
        </span>
      </NavBarButton>
    </nav>
  );
}
