import { VIEWPORT_HEIGHT, VIEWPORT_WIDTH } from '../../domain/Constants';
import { isVkDesktopPlatform } from '../vk/launchParams';

export type FitScale = { x: number; y: number };

/** Visible host size (iframe-safe: prefer visualViewport / client size). */
export function getHostViewportSize(
  win: Pick<Window, 'innerWidth' | 'innerHeight' | 'visualViewport'> = window,
  docEl: Pick<Element, 'clientWidth' | 'clientHeight'> = document.documentElement,
): { width: number; height: number } {
  const vv = win.visualViewport;
  const width = vv?.width || docEl.clientWidth || win.innerWidth;
  const height = vv?.height || docEl.clientHeight || win.innerHeight;
  return { width, height };
}

/**
 * Desktop / PC host: VK desktop platforms, or a landscape window
 * (VK desktop iframe is wide; phones are portrait).
 */
export function isDesktopHost(
  size: { width: number; height: number } = getHostViewportSize(),
): boolean {
  if (isVkDesktopPlatform()) {
    return true;
  }
  return size.width > size.height;
}

/**
 * PC: contain (fit entire design in the window, letterbox).
 * Mobile: cover (fill without stretching; may crop when aspect differs).
 */
export function computeFitScale(
  size: { width: number; height: number } = getHostViewportSize(),
  desktop: boolean = isDesktopHost(size),
): FitScale {
  if (desktop) {
    const uniform = Math.min(size.width / VIEWPORT_WIDTH, size.height / VIEWPORT_HEIGHT);
    return { x: uniform, y: uniform };
  }
  // Fill the window without stretching; may crop edges when aspect differs.
  const uniform = Math.max(size.width / VIEWPORT_WIDTH, size.height / VIEWPORT_HEIGHT);
  return { x: uniform, y: uniform };
}
