/**
 * Design-space positions from map.svg `#giants` groups,
 * scaled SVG (2222×1263) → world (9960×5662).
 *
 * Single PNG per giant: idle === hover === group bbox.
 */
import type { GiantId } from '../../../../domain/ids/ids';

export type { GiantId };

export type GiantImagePlacement = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export type GiantPlacement = {
  id: GiantId;
  left: number;
  top: number;
  width: number;
  height: number;
  idle: GiantImagePlacement;
  hover: GiantImagePlacement;
};

function placement(
  id: GiantId,
  box: GiantImagePlacement,
): GiantPlacement {
  return {
    id,
    ...box,
    idle: box,
    hover: box,
  };
}

