import '../components/atomic/layout/app_screen/app_screen.css';
import { FrameHeader } from '../components/atomic/dialog/frame_header/FrameHeader';
import { SolidFrameBackground } from '../components/atomic/dialog/solid_frame_background/SolidFrameBackground';
import { SkyAtmosphere } from '../components/composite/atmosphere/sky_atmosphere/SkyAtmosphere';
import type { ScreenViewProps } from '../shared/screenViewProps';
import { Button } from './button/Button';
import { ClaudiSticker } from './content/ClaudiSticker';
import { OpenedStickerBackground } from './content/OpenedStickerBackground';
import { RewardPopup } from './content/RewardPopup';
import { Decor } from './decor/Decor';
import { StickerShine } from './decor/StickerShine';
import type { StickerRewardScreenController } from './StickerRewardScreenController';
import type { StickerRewardScreenModel } from './StickerRewardScreenModelScreen';
import { HeaderText } from './texts/HeaderText';
import './sticker_reward_screen.css';

export type StickerRewardScreenViewProps = ScreenViewProps<
  StickerRewardScreenModel,
  StickerRewardScreenController
>;

/** Sticker reward screen stub. */
export function StickerRewardScreenView({
  controller,
}: StickerRewardScreenViewProps) {
  return (
    <div className="app-screen sticker-reward-screen">
      <SkyAtmosphere variant="delivery" />
      <SolidFrameBackground />
      <FrameHeader showSubHeader={false} />
      <HeaderText />
      <OpenedStickerBackground />
      <StickerShine />
      <Decor />
      <RewardPopup />
      <ClaudiSticker />
      <Button onClick={controller.handleClaim} />
    </div>
  );
}
