import {
  CLAUDI_STICKERS,
  type ClaudiStickerId,
} from '../../../../domain';
import claudiAllHeroesImg from '../../components/atomic/icons/stickers/claudi_all_heroes.png';
import claudiAlmostLateImg from '../../components/atomic/icons/stickers/claudi_almost_late.png';
import claudiBoostPerfectImg from '../../components/atomic/icons/stickers/claudi_boost_perfect.png';
import claudiBumpyImg from '../../components/atomic/icons/stickers/claudi_bumpy.png';
import claudiFirstSuccessImg from '../../components/atomic/icons/stickers/claudi_first_success.png';
import claudiHeartbreakerImg from '../../components/atomic/icons/stickers/claudi_heartbreaker.png';
import claudiNimbleImg from '../../components/atomic/icons/stickers/claudi_nimble.png';
import claudiNoBoostImg from '../../components/atomic/icons/stickers/claudi_no_boost.png';
import claudiSecondChanceImg from '../../components/atomic/icons/stickers/claudi_second_chance.png';
import claudiSweetDietImg from '../../components/atomic/icons/stickers/claudi_sweet_diet.png';
import claudiSweetRideImg from '../../components/atomic/icons/stickers/claudi_sweet_ride.png';
import claudiTidyImg from '../../components/atomic/icons/stickers/claudi_tidy.png';
import claudiWorseReplayImg from '../../components/atomic/icons/stickers/claudi_worse_replay.png';
import { StickerItem, type StickerItemLayout } from '../sticker_item/StickerItem';
import './StickersGrid.css';

const STICKER_ICONS: Record<ClaudiStickerId, string> = {
  claudi_first_success: claudiFirstSuccessImg,
  claudi_sweet_ride: claudiSweetRideImg,
  claudi_nimble: claudiNimbleImg,
  claudi_boost_perfect: claudiBoostPerfectImg,
  claudi_tidy: claudiTidyImg,
  claudi_second_chance: claudiSecondChanceImg,
  claudi_all_heroes: claudiAllHeroesImg,
  claudi_almost_late: claudiAlmostLateImg,
  claudi_sweet_diet: claudiSweetDietImg,
  claudi_heartbreaker: claudiHeartbreakerImg,
  claudi_bumpy: claudiBumpyImg,
  claudi_worse_replay: claudiWorseReplayImg,
  claudi_no_boost: claudiNoBoostImg,
};

/** Figma Group 1321317897 (160:16959) — five icon slots per page. */
const ICON_SLOTS: readonly StickerItemLayout[] = [
  {
    left: 122,
    top: 345.4716796875,
    width: 369.45343017578125,
    height: 336.3664245605469,
  },
  {
    left: 545,
    top: 580.2763671875,
    width: 415.21636962890625,
    height: 243.24313354492188,
  },
  {
    left: 97.61572265625,
    top: 966.1086044311523,
    width: 417.54972963355794,
    height: 231.72020091438708,
  },
  {
    left: 598.16845703125,
    top: 1082.6015625,
    width: 308.0355224609375,
    height: 294.9913330078125,
  },
  {
    left: 161,
    top: 1481.59765625,
    width: 299.8909606933594,
    height: 305.4585876464844,
  },
];

const FIRST_SLOT = ICON_SLOTS[0];
const LAST_SLOT = ICON_SLOTS[ICON_SLOTS.length - 1];
/** Same vertical gap as between slot 4 bottom and slot 5 top. */
const PAGE_GAP =
  LAST_SLOT.top - (ICON_SLOTS[3].top + ICON_SLOTS[3].height);

/**
 * Next page starts below the last sticker, not on its slot
 * (old step g_5.top − s_1.top stacked page 1 onto g_5).
 */
export const STICKERS_PAGE_STEP =
  LAST_SLOT.top + LAST_SLOT.height + PAGE_GAP - FIRST_SLOT.top;

const STICKERS = CLAUDI_STICKERS.map((def, index) => {
  const slot = ICON_SLOTS[index % ICON_SLOTS.length];
  const pageIndex = Math.floor(index / ICON_SLOTS.length);
  return {
    id: def.id,
    name: def.name,
    iconSrc: STICKER_ICONS[def.id],
    iconLayout: {
      ...slot,
      top: slot.top + pageIndex * STICKERS_PAGE_STEP,
    },
  };
});

export type StickersGridProps = {
  /** Page index; each step shifts the group by STICKERS_PAGE_STEP. */
  page?: number;
  isStickerUnlocked?: (id: ClaudiStickerId) => boolean;
  onStickerClick?: () => void;
};

/** Stickers row from Figma 160:16959 — translates as one group per arrow page. */
export function StickersGrid({
  page = 0,
  isStickerUnlocked,
  onStickerClick,
}: StickersGridProps) {
  return (
    <div
      className="stickers-grid"
      style={{ transform: `translateY(${-page * STICKERS_PAGE_STEP}px)` }}
    >
      {STICKERS.map((sticker) => (
        <StickerItem
          key={sticker.id}
          iconSrc={sticker.iconSrc}
          iconLayout={sticker.iconLayout}
          ariaLabel={sticker.name}
          isUnlocked={isStickerUnlocked?.(sticker.id) ?? false}
          onClick={onStickerClick}
        />
      ))}
    </div>
  );
}
