import uiClickUrl from './sounds/sfx/ui_click.mp3';
import uiClickBUrl from './sounds/sfx/ui_click_b.mp3';
import uiInfoUrl from './sounds/sfx/ui_info.mp3';
import uiInfoBUrl from './sounds/sfx/ui_info_b.mp3';
import deliveryTakeUrl from './sounds/sfx/delivery_take.mp3';
import deliveryTakeBUrl from './sounds/sfx/delivery_take_b.mp3';
import deliverySuccessUrl from './sounds/sfx/delivery_success.mp3';
import deliveryFailUrl from './sounds/sfx/delivery_fail.mp3';
import runnerHitUrl from './sounds/sfx/runner_hit.mp3';
import runnerHitBUrl from './sounds/sfx/runner_hit_b.mp3';
import runnerSparkUrl from './sounds/sfx/runner_spark.mp3';
import runnerSparkBUrl from './sounds/sfx/runner_spark_b.mp3';
import runnerBoosterUrl from './sounds/sfx/runner_booster.mp3';
import runnerBoosterBUrl from './sounds/sfx/runner_booster_b.mp3';
import runnerFinishUrl from './sounds/sfx/runner_finish.mp3';
import loadingSfxUrl from './sounds/sfx/loading_sfx.mp3';

export const SOUND_IDS = [
  'ui.click',
  'ui.click_b',
  'ui.info',
  'ui.info_b',
  'delivery.take',
  'delivery.take_b',
  'delivery.success',
  'delivery.fail',
  'runner.hit',
  'runner.hit_b',
  'runner.spark',
  'runner.spark_b',
  'runner.booster',
  'runner.booster_b',
  'runner.finish',
  'loading.sfx',
] as const;

export type SoundId = (typeof SOUND_IDS)[number];

export const soundUrls: Readonly<Record<SoundId, string>> = {
  'ui.click': uiClickUrl,
  'ui.click_b': uiClickBUrl,
  'ui.info': uiInfoUrl,
  'ui.info_b': uiInfoBUrl,
  'delivery.take': deliveryTakeUrl,
  'delivery.take_b': deliveryTakeBUrl,
  'delivery.success': deliverySuccessUrl,
  'delivery.fail': deliveryFailUrl,
  'runner.hit': runnerHitUrl,
  'runner.hit_b': runnerHitBUrl,
  'runner.spark': runnerSparkUrl,
  'runner.spark_b': runnerSparkBUrl,
  'runner.booster': runnerBoosterUrl,
  'runner.booster_b': runnerBoosterBUrl,
  'runner.finish': runnerFinishUrl,
  'loading.sfx': loadingSfxUrl,
};

export function getSoundUrl(id: SoundId): string {
  return soundUrls[id];
}
