export function getItemsLayoutForGiant(
  giantId: GiantId,
  orderIndex = 0,
): GiantItemsLayout {
  const variants = GIANT_ITEMS_LAYOUT[giantId];
  const index = Math.min(variants.length - 1, Math.max(0, Math.floor(orderIndex)));
  return variants[index];
}
