import './Shine.css';

export type ShineVariant = 'delivery' | 'welcome';

export type ShineProps = {
  variant?: ShineVariant;
  className?: string;
};

/** Warm overlay glow — delivery (Figma shine) or welcome (DecorShine ellipses). */
export function Shine({ variant = 'delivery', className }: ShineProps) {
  return (
    <div
      className={['shine', `shine--${variant}`, className]
        .filter(Boolean)
        .join(' ')}
      aria-hidden
    >
      <div className="shine__ellipse shine__ellipse--1" />
      <div className="shine__ellipse shine__ellipse--2" />
    </div>
  );
}
