import type { RunnerDecorSprite, RunnerLevel } from './runnerTypes';

/**
 * `mona/modificators.svg` — отдельный артборд (viewBox 3111×2053), не совпадает по
 * масштабу с viewBox маршрута (13671×930), поэтому координаты используются только
 * как пропорции (порядок и относительное расположение), а не абсолютные S/lane.
 */
const MODIFICATORS_CANVAS_WIDTH = 3111;
const MODIFICATORS_CANVAS_HEIGHT = 2053;

type MonaCrystalDef = {
  id: string;
  /** Центр bbox группы `#1`..`#5` в mona/modificators.svg. */
  centerX: number;
  centerY: number;
};

/** Центры bbox групп `#1`..`#5` из mona/modificators.svg. */
const MONA_CRYSTAL_DEFS: readonly MonaCrystalDef[] = [
  { id: 'mona_m_1', centerX: 1375.275, centerY: 1531.905 },
  { id: 'mona_m_2', centerX: 799.456, centerY: 1487.485 },
  { id: 'mona_m_3', centerX: 1174.12, centerY: 1118.395 },
  { id: 'mona_m_4', centerX: 1840.6, centerY: 1286.4815 },
  { id: 'mona_m_5', centerX: 2209.62, centerY: 1096.046 },
] as const;

/** Соотношение сторон obstacles/m.png (442×652), для расчёта высоты по ширине. */
const MONA_M_ASPECT = 652 / 442;

/** Ширина спрайта в S-юнитах (маршрут). */
const MONA_M_WIDTH_S = 320;

/** Якорь смещён вниз: (centerS, centerLane) — это низ кристалла, а не центр спрайта. */
const MONA_M_ANCHOR = { x: 0.5, y: 0.85 } as const;

const MONA_M_SPIN_DURATION_SEC = 6;

/**
 * 5 кристаллов mona: без хитбокса (только декор), поверх игрока, крутятся на 360°.
 * Позиции `#1`..`#5` из modificators.svg распределены пропорционально внутри
 * общей modifier-зоны маршрута (свой artboard не совпадает по масштабу с маршрутом).
 */
export function buildMonaCrystalDecor(level: RunnerLevel): RunnerDecorSprite[] {
  if (level.giantId !== 'mona' || level.modifierZone == null) {
    return [];
  }
  const { fromS, toS } = level.modifierZone;
  const zoneWidthS = toS - fromS;
  const heightLane = (MONA_M_WIDTH_S * MONA_M_ASPECT) / level.viewBox.height;
  return MONA_CRYSTAL_DEFS.map((def) => {
    const fracX = def.centerX / MODIFICATORS_CANVAS_WIDTH;
    const fracLane = 1 - def.centerY / MODIFICATORS_CANVAS_HEIGHT;
    const centerS = fromS + fracX * zoneWidthS;
    const centerLane = level.laneMin + fracLane * (level.laneMax - level.laneMin);
    return {
      id: def.id,
      spriteKey: 'mona_m',
      centerS,
      centerLane,
      widthS: MONA_M_WIDTH_S,
      heightLane,
      layer: 'front',
      anchor: MONA_M_ANCHOR,
      spinDurationSec: MONA_M_SPIN_DURATION_SEC,
    };
  });
}
